// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { IOmnichainGovernanceExecutor } from "./interfaces/IOmnichainGovernanceExecutor.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";

/**
 * @title OmnichainExecutorOwner
 * @author Venus
 * @notice OmnichainProposalSender contract acts as a governance and access control mechanism,
 * allowing owner to upsert signature of OmnichainGovernanceExecutor contract,
 * also contains function to transfer the ownership of contract as well.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */

contract OmnichainExecutorOwner is AccessControlledV8 {
    /**
     *  @custom:oz-upgrades-unsafe-allow state-variable-immutable
     */
    IOmnichainGovernanceExecutor public immutable OMNICHAIN_GOVERNANCE_EXECUTOR;

    /**
     * @notice Stores function signature corresponding to their 4 bytes hash value
     */
    mapping(bytes4 => string) public functionRegistry;

    /**
     * @notice Event emitted when function registry updated
     */
    event FunctionRegistryChanged(string indexed signature, bool active);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address omnichainGovernanceExecutor_) {
        require(omnichainGovernanceExecutor_ != address(0), "Address must not be zero");
        OMNICHAIN_GOVERNANCE_EXECUTOR = IOmnichainGovernanceExecutor(omnichainGovernanceExecutor_);
        _disableInitializers();
    }

    /**
     * @notice Initialize the contract
     * @param accessControlManager_  Address of access control manager
     */
    function initialize(address accessControlManager_) external initializer {
        require(accessControlManager_ != address(0), "Address must not be zero");
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Sets the source message sender address
     * @param srcChainId_ The LayerZero id of a source chain
     * @param srcAddress_ The address of the contract on the source chain
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits SetTrustedRemoteAddress with source chain Id and source address
     */
    function setTrustedRemoteAddress(uint16 srcChainId_, bytes calldata srcAddress_) external {
        _checkAccessAllowed("setTrustedRemoteAddress(uint16,bytes)");
        require(srcChainId_ != 0, "ChainId must not be zero");
        ensureNonzeroAddress(address(uint160(bytes20(srcAddress_))));
        require(srcAddress_.length == 20, "Source address must be 20 bytes long");
        OMNICHAIN_GOVERNANCE_EXECUTOR.setTrustedRemoteAddress(srcChainId_, srcAddress_);
    }

    /**
     * @notice Invoked when called function does not exist in the contract
     * @param data_ Calldata containing the encoded function call
     * @return Result of function call
     * @custom:access Controlled by Access Control Manager
     */
    fallback(bytes calldata data_) external returns (bytes memory) {
        string memory fun = functionRegistry[msg.sig];
        require(bytes(fun).length != 0, "Function not found");
        _checkAccessAllowed(fun);
        (bool ok, bytes memory res) = address(OMNICHAIN_GOVERNANCE_EXECUTOR).call(data_);
        require(ok, "call failed");
        return res;
    }

    /**
     * @notice A registry of functions that are allowed to be executed from proposals
     * @param signatures_  Function signature to be added or removed
     * @param active_ bool value, should be true to add function
     * @custom:access Only owner
     */
    function upsertSignature(string[] calldata signatures_, bool[] calldata active_) external onlyOwner {
        uint256 signatureLength = signatures_.length;
        require(signatureLength == active_.length, "Input arrays must have the same length");
        for (uint256 i; i < signatureLength; ++i) {
            bytes4 sigHash = bytes4(keccak256(bytes(signatures_[i])));
            bytes memory signature = bytes(functionRegistry[sigHash]);
            if (active_[i] && signature.length == 0) {
                functionRegistry[sigHash] = signatures_[i];
                emit FunctionRegistryChanged(signatures_[i], true);
            } else if (!active_[i] && signature.length != 0) {
                delete functionRegistry[sigHash];
                emit FunctionRegistryChanged(signatures_[i], false);
            }
        }
    }

    /**
     * @notice This function transfer the ownership of the executor from this contract to new owner
     * @param newOwner_ New owner of the governanceExecutor
     * @custom:access Controlled by AccessControlManager
     */

    function transferBridgeOwnership(address newOwner_) external {
        _checkAccessAllowed("transferBridgeOwnership(address)");
        require(newOwner_ != address(0), "Address must not be zero");
        OMNICHAIN_GOVERNANCE_EXECUTOR.transferOwnership(newOwner_);
    }

    /**
     *  @notice Empty implementation of renounce ownership to avoid any mishappening
     */
    function renounceOwnership() public virtual override {}
}

contracts/Cross-chain/OmnichainGovernanc.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { BytesLib } from "@layerzerolabs/solidity-examples/contracts/libraries/BytesLib.sol";
import { ExcessivelySafeCall } from "@layerzerolabs/solidity-examples/contracts/libraries/ExcessivelySafeCall.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { BaseOmnichainControllerDest } from "./BaseOmnichainControllerDest.sol";
import { ITimelock } from "./interfaces/ITimelock.sol";

/**
 * @title OmnichainGovernanceExecutor
 * @notice Executes the proposal transactions sent from the main chain
 * @dev The owner of this contract controls LayerZero configuration. When used in production the owner will be OmnichainExecutor
 * This implementation is non-blocking, meaning the failed messages will not block the future messages from the source.
 * For the blocking behavior, derive the contract from LzApp.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract OmnichainGovernanceExecutor is ReentrancyGuard, BaseOmnichainControllerDest {
    using BytesLib for bytes;
    using ExcessivelySafeCall for address;

    enum ProposalType {
        NORMAL,
        FASTTRACK,
        CRITICAL
    }

    struct Proposal {
        /** Unique id for looking up a proposal */
        uint256 id;
        /** The timestamp that the proposal will be available for execution, set once the vote succeeds */
        uint256 eta;
        /** The ordered list of target addresses for calls to be made */
        address[] targets;
        /** The ordered list of values (i.e. msg.value) to be passed to the calls to be made */
        uint256[] values;
        /** The ordered list of function signatures to be called */
        string[] signatures;
        /** The ordered list of calldata to be passed to each call */
        bytes[] calldatas;
        /** Flag marking whether the proposal has been canceled */
        bool canceled;
        /** Flag marking whether the proposal has been executed */
        bool executed;
        /** The type of the proposal */
        uint8 proposalType;
    }
    /*
     * @notice Possible states that a proposal may be in
     */
    enum ProposalState {
        Canceled,
        Queued,
        Executed
    }

    /**
     * @notice A privileged role that can cancel any proposal
     */
    address public guardian;

    /**
     * @notice Stores BNB chain layerzero endpoint id
     */
    uint16 public srcChainId;

    /**
     * @notice Last proposal count received
     */
    uint256 public lastProposalReceived;

    /**
     * @notice The official record of all proposals ever proposed
     */
    mapping(uint256 => Proposal) public proposals;

    /**
     * @notice Mapping containing Timelock addresses for each proposal type
     */
    mapping(uint256 => ITimelock) public proposalTimelocks;

    /**
     * @notice Represents queue state of proposal
     */
    mapping(uint256 => bool) public queued;

    /**
     * @notice Emitted when proposal is received
     */
    event ProposalReceived(
        uint256 indexed proposalId,
        address[] targets,
        uint256[] values,
        string[] signatures,
        bytes[] calldatas,
        uint8 proposalType
    );

    /**
     * @notice Emitted when proposal is queued
     */
    event ProposalQueued(uint256 indexed id, uint256 eta);

    /**
     * Emitted when proposal executed
     */
    event ProposalExecuted(uint256 indexed id);

    /**
     * @notice Emitted when proposal failed
     */
    event ReceivePayloadFailed(uint16 indexed srcChainId, bytes indexed srcAddress, uint64 nonce, bytes reason);

    /**
     * @notice Emitted when proposal is canceled
     */
    event ProposalCanceled(uint256 indexed id);

    /**
     * @notice Emitted when timelock added
     */
    event TimelockAdded(uint8 routeType, address indexed oldTimelock, address indexed newTimelock);

    /**
     * @notice Emitted when source layerzero endpoint id is updated
     */
    event SetSrcChainId(uint16 indexed oldSrcChainId, uint16 indexed newSrcChainId);

    /**
     * @notice Emitted when new guardian address is set
     */
    event NewGuardian(address indexed oldGuardian, address indexed newGuardian);

    /**
     * @notice Emitted when pending admin of Timelock is updated
     */
    event SetTimelockPendingAdmin(address, uint8);

    /**
     * @notice Thrown when proposal ID is invalid
     */
    error InvalidProposalId();

    constructor(address endpoint_, address guardian_, uint16 srcChainId_) BaseOmnichainControllerDest(endpoint_) {
        ensureNonzeroAddress(guardian_);
        guardian = guardian_;
        srcChainId = srcChainId_;
    }

    /**
     * @notice Update source layerzero endpoint id
     * @param srcChainId_ The new source chain id to be set
     * @custom:event Emit SetSrcChainId with old and new source id
     * @custom:access Only owner
     */
    function setSrcChainId(uint16 srcChainId_) external onlyOwner {
        emit SetSrcChainId(srcChainId, srcChainId_);
        srcChainId = srcChainId_;
    }

    /**
     * @notice Sets the new executor guardian
     * @param newGuardian The address of the new guardian
     * @custom:access Must be call by guardian or owner
     * @custom:event Emit NewGuardian with old and new guardian address
     */
    function setGuardian(address newGuardian) external {
        require(
            msg.sender == guardian || msg.sender == owner(),
            "OmnichainGovernanceExecutor::setGuardian: owner or guardian only"
        );
        ensureNonzeroAddress(newGuardian);
        emit NewGuardian(guardian, newGuardian);
        guardian = newGuardian;
    }

    /**
     * @notice Add timelocks to the ProposalTimelocks mapping
     * @param timelocks_ Array of addresses of all 3 timelocks
     * @custom:access Only owner
     * @custom:event Emits TimelockAdded with old and new timelock and route type
     */
    function addTimelocks(ITimelock[] memory timelocks_) external onlyOwner {
        uint8 length = uint8(type(ProposalType).max) + 1;
        require(
            timelocks_.length == length,
            "OmnichainGovernanceExecutor::addTimelocks:number of timelocks should match the number of governance routes"
        );
        for (uint8 i; i < length; ++i) {
            ensureNonzeroAddress(address(timelocks_[i]));
            emit TimelockAdded(i, address(proposalTimelocks[i]), address(timelocks_[i]));
            proposalTimelocks[i] = timelocks_[i];
        }
    }

    /**
     * @notice Executes a queued proposal if eta has passed
     * @param proposalId_ Id of proposal that is to be executed
     * @custom:event Emits ProposalExecuted with proposal id of executed proposal
     */
    function execute(uint256 proposalId_) external nonReentrant {
        require(
            state(proposalId_) == ProposalState.Queued,
            "OmnichainGovernanceExecutor::execute: proposal can only be executed if it is queued"
        );

        Proposal storage proposal = proposals[proposalId_];
        proposal.executed = true;
        ITimelock timelock = proposalTimelocks[proposal.proposalType];
        uint256 eta = proposal.eta;
        uint256 length = proposal.targets.length;

        emit ProposalExecuted(proposalId_);

        for (uint256 i; i < length; ++i) {
            timelock.executeTransaction(
                proposal.targets[i],
                proposal.values[i],
                proposal.signatures[i],
                proposal.calldatas[i],
                eta
            );
        }
        delete queued[proposalId_];
    }

    /**
     * @notice Cancels a proposal only if sender is the guardian and proposal is not executed
     * @param proposalId_ Id of proposal that is to be canceled
     * @custom:access Sender must be the guardian
     * @custom:event Emits ProposalCanceled with proposal id of the canceled proposal
     */
    function cancel(uint256 proposalId_) external {
        require(
            state(proposalId_) == ProposalState.Queued,
            "OmnichainGovernanceExecutor::cancel: proposal should be queued and not executed"
        );
        Proposal storage proposal = proposals[proposalId_];
        require(msg.sender == guardian, "OmnichainGovernanceExecutor::cancel: sender must be guardian");

        proposal.canceled = true;
        ITimelock timelock = proposalTimelocks[proposal.proposalType];
        uint256 eta = proposal.eta;
        uint256 length = proposal.targets.length;

        emit ProposalCanceled(proposalId_);

        for (uint256 i; i < length; ++i) {
            timelock.cancelTransaction(
                proposal.targets[i],
                proposal.values[i],
                proposal.signatures[i],
                proposal.calldatas[i],
                eta
            );
        }
        delete queued[proposalId_];
    }

    /**
     * @notice Sets the new pending admin of the Timelock
     * @param pendingAdmin_ Address of new pending admin
     * @param proposalType_ Type of proposal
     * @custom:access Only owner
     * @custom:event Emits SetTimelockPendingAdmin with new pending admin and proposal type
     */
    function setTimelockPendingAdmin(address pendingAdmin_, uint8 proposalType_) external onlyOwner {
        uint8 proposalTypeLength = uint8(type(ProposalType).max) + 1;
        require(
            proposalType_ < proposalTypeLength,
            "OmnichainGovernanceExecutor::setTimelockPendingAdmin: invalid proposal type"
        );

        proposalTimelocks[proposalType_].setPendingAdmin(pendingAdmin_);
        emit SetTimelockPendingAdmin(pendingAdmin_, proposalType_);
    }

    /**
     * @notice Resends a previously failed message
     * @param srcChainId_ Source chain Id
     * @param srcAddress_ Source address => local app address + remote app address
     * @param nonce_ Nonce to identify failed message
     * @param payload_ The payload of the message to be retried
     * @custom:access Only owner
     */
    function retryMessage(
        uint16 srcChainId_,
        bytes calldata srcAddress_,
        uint64 nonce_,
        bytes calldata payload_
    ) public payable override onlyOwner nonReentrant {
        require(
            keccak256(trustedRemoteLookup[srcChainId_]) == keccak256(srcAddress_),
            "OmnichainGovernanceExecutor::retryMessage: not a trusted remote"
        );
        super.retryMessage(srcChainId_, srcAddress_, nonce_, payload_);
    }

    /**
     * @notice Gets the state of a proposal
     * @param proposalId_ The id of the proposal
     * @return Proposal state
     */
    function state(uint256 proposalId_) public view returns (ProposalState) {
        Proposal storage proposal = proposals[proposalId_];
        if (proposal.canceled) {
            return ProposalState.Canceled;
        } else if (proposal.executed) {
            return ProposalState.Executed;
        } else if (queued[proposalId_]) {
            // queued only when proposal is received
            return ProposalState.Queued;
        } else {
            revert InvalidProposalId();
        }
    }

    /**
     * @notice Process blocking LayerZero receive request
     * @param srcChainId_ Source chain Id
     * @param srcAddress_ Source address from which payload is received
     * @param nonce_ Nonce associated with the payload to prevent replay attacks
     * @param payload_ Encoded payload containing proposal information
     * @custom:event Emit ReceivePayloadFailed if call fails
     */
    function _blockingLzReceive(
        uint16 srcChainId_,
        bytes memory srcAddress_,
        uint64 nonce_,
        bytes memory payload_
    ) internal virtual override {
        require(srcChainId_ == srcChainId, "OmnichainGovernanceExecutor::_blockingLzReceive: invalid source chain id");
        bytes32 hashedPayload = keccak256(payload_);
        bytes memory callData = abi.encodeCall(this.nonblockingLzReceive, (srcChainId_, srcAddress_, nonce_, payload_));

        (bool success, bytes memory reason) = address(this).excessivelySafeCall(gasleft() - 30000, 150, callData);
        // try-catch all errors/exceptions
        if (!success) {
            failedMessages[srcChainId_][srcAddress_][nonce_] = hashedPayload;
            emit ReceivePayloadFailed(srcChainId_, srcAddress_, nonce_, reason); // Retrieve payload from the src side tx if needed to clear
        }
    }

    /**
     * @notice Process non blocking LayerZero receive request
     * @param payload_ Encoded payload containing proposal information
     * @custom:event Emit ProposalReceived
     */
    function _nonblockingLzReceive(
        uint16,
        bytes memory,
        uint64,
        bytes memory payload_
    ) internal virtual override whenNotPaused {
        (bytes memory payload, uint256 pId) = abi.decode(payload_, (bytes, uint256));
        (
            address[] memory targets,
            uint256[] memory values,
            string[] memory signatures,
            bytes[] memory calldatas,
            uint8 pType
        ) = abi.decode(payload, (address[], uint256[], string[], bytes[], uint8));
        require(proposals[pId].id == 0, "OmnichainGovernanceExecutor::_nonblockingLzReceive: duplicate proposal");
        require(
            targets.length == values.length &&
                targets.length == signatures.length &&
                targets.length == calldatas.length,
            "OmnichainGovernanceExecutor::_nonblockingLzReceive: proposal function information arity mismatch"
        );
        require(
            pType < uint8(type(ProposalType).max) + 1,
            "OmnichainGovernanceExecutor::_nonblockingLzReceive: invalid proposal type"
        );
        _isEligibleToReceive(targets.length);

        Proposal memory newProposal = Proposal({
            id: pId,
            eta: 0,
            targets: targets,
            values: values,
            signatures: signatures,
            calldatas: calldatas,
            canceled: false,
            executed: false,
            proposalType: pType
        });

        proposals[pId] = newProposal;
        lastProposalReceived = pId;

        emit ProposalReceived(newProposal.id, targets, values, signatures, calldatas, pType);
        _queue(pId);
    }

    /**
     * @notice Queue proposal for execution
     * @param proposalId_ Proposal to be queued
     * @custom:event Emit ProposalQueued with proposal id and eta
     */
    function _queue(uint256 proposalId_) internal {
        Proposal storage proposal = proposals[proposalId_];
        uint256 eta = block.timestamp + proposalTimelocks[proposal.proposalType].delay();

        proposal.eta = eta;
        queued[proposalId_] = true;
        uint8 proposalType = proposal.proposalType;
        uint256 length = proposal.targets.length;
        emit ProposalQueued(proposalId_, eta);

        for (uint256 i; i < length; ++i) {
            _queueOrRevertInternal(
                proposal.targets[i],
                proposal.values[i],
                proposal.signatures[i],
                proposal.calldatas[i],
                eta,
                proposalType
            );
        }
    }

    /**
     * @notice Check for unique proposal
     * @param target_ Address of the contract with the method to be called
     * @param value_ Native token amount sent with the transaction
     * @param signature_ Signature of the function to be called
     * @param data_ Arguments to be passed to the function when called
     * @param eta_ Timestamp after which the transaction can be executed
     * @param proposalType_ Type of proposal
     */
    function _queueOrRevertInternal(
        address target_,
        uint256 value_,
        string memory signature_,
        bytes memory data_,
        uint256 eta_,
        uint8 proposalType_
    ) internal {
        require(
            !proposalTimelocks[proposalType_].queuedTransactions(
                keccak256(abi.encode(target_, value_, signature_, data_, eta_))
            ),
            "OmnichainGovernanceExecutor::queueOrRevertInternal: identical proposal action already queued at eta"
        );

        proposalTimelocks[proposalType_].queueTransaction(target_, value_, signature_, data_, eta_);
    }
}

contracts/Cross-chain/OmnichainProposalS.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.25;

import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { ILayerZeroEndpoint } from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroEndpoint.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { BaseOmnichainControllerSrc } from "./BaseOmnichainControllerSrc.sol";

/**
 * @title OmnichainProposalSender
 * @author Venus
 * @notice OmnichainProposalSender contract builds upon the functionality of its parent contract , BaseOmnichainControllerSrc
 * It sends a proposal's data to remote chains for execution after the proposal passes on the main chain
 * when used with GovernorBravo, the owner of this contract must be set to the Timelock contract
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */

contract OmnichainProposalSender is ReentrancyGuard, BaseOmnichainControllerSrc {
    /**
     * @notice Stores the total number of remote proposals
     */
    uint256 public proposalCount;

    /**
     * @notice Execution hashes of failed messages
     * @dev [proposalId] -> [executionHash]
     */
    mapping(uint256 => bytes32) public storedExecutionHashes;

    /**
     * @notice LayerZero endpoint for sending messages to remote chains
     */
    ILayerZeroEndpoint public immutable LZ_ENDPOINT;

    /**
     * @notice Specifies the allowed path for sending messages (remote chainId => remote app address + local app address)
     */
    mapping(uint16 => bytes) public trustedRemoteLookup;

    /**
     * @notice Emitted when a remote message receiver is set for the remote chain
     */
    event SetTrustedRemoteAddress(uint16 indexed remoteChainId, bytes oldRemoteAddress, bytes newRemoteAddress);

    /**
     * @notice Event emitted when trusted remote sets to empty
     */
    event TrustedRemoteRemoved(uint16 indexed chainId);

    /**
     * @notice Emitted when a proposal execution request is sent to the remote chain
     */
    event ExecuteRemoteProposal(uint16 indexed remoteChainId, uint256 proposalId, bytes payload);

    /**
     * @notice Emitted when a previously failed message is successfully sent to the remote chain
     */
    event ClearPayload(uint256 indexed proposalId, bytes32 executionHash);

    /**
     * @notice Emitted when an execution hash of a failed message is saved
     */
    event StorePayload(
        uint256 indexed proposalId,
        uint16 indexed remoteChainId,
        bytes payload,
        bytes adapterParams,
        uint256 value,
        bytes reason
    );
    /**
     * @notice Emitted while fallback withdraw
     */
    event FallbackWithdraw(address indexed receiver, uint256 value);

    constructor(
        ILayerZeroEndpoint lzEndpoint_,
        address accessControlManager_
    ) BaseOmnichainControllerSrc(accessControlManager_) {
        ensureNonzeroAddress(address(lzEndpoint_));
        LZ_ENDPOINT = lzEndpoint_;
    }

    /**
     * @notice Estimates LayerZero fees for cross-chain message delivery to the remote chain
     * @dev The estimated fees are the minimum required; it's recommended to increase the fees amount when sending a message. The unused amount will be refunded
     * @param remoteChainId_ The LayerZero id of a remote chain
     * @param payload_ The payload to be sent to the remote chain. It's computed as follows:
     * payload = abi.encode(abi.encode(targets, values, signatures, calldatas, proposalType), pId)
     * @param useZro_ Bool that indicates whether to pay in ZRO tokens or not
     * @param adapterParams_ The params used to specify the custom amount of gas required for the execution on the destination
     * @return nativeFee The amount of fee in the native gas token (e.g. ETH)
     * @return zroFee The amount of fee in ZRO token
     */
    function estimateFees(
        uint16 remoteChainId_,
        bytes calldata payload_,
        bool useZro_,
        bytes calldata adapterParams_
    ) external view returns (uint256, uint256) {
        return LZ_ENDPOINT.estimateFees(remoteChainId_, address(this), payload_, useZro_, adapterParams_);
    }

    /**
     * @notice Remove trusted remote from storage
     * @param remoteChainId_ The chain's id corresponds to setting the trusted remote to empty
     * @custom:access Controlled by Access Control Manager
     * @custom:event Emit TrustedRemoteRemoved with remote chain id
     */
    function removeTrustedRemote(uint16 remoteChainId_) external {
        _ensureAllowed("removeTrustedRemote(uint16)");
        require(trustedRemoteLookup[remoteChainId_].length != 0, "OmnichainProposalSender: trusted remote not found");
        delete trustedRemoteLookup[remoteChainId_];
        emit TrustedRemoteRemoved(remoteChainId_);
    }

    /**
     * @notice Sends a message to execute a remote proposal
     * @dev Stores the hash of the execution parameters if sending fails (e.g., due to insufficient fees)
     * @param remoteChainId_ The LayerZero id of the remote chain
     * @param payload_ The payload to be sent to the remote chain
     * It's computed as follows: payload = abi.encode(targets, values, signatures, calldatas, proposalType)
     * @param adapterParams_ The params used to specify the custom amount of gas required for the execution on the destination
     * @param zroPaymentAddress_ The address of the ZRO token holder who would pay for the transaction. This must be either address(this) or tx.origin
     * @custom:event Emits ExecuteRemoteProposal with remote chain id, proposal ID and payload on success
     * @custom:event Emits StorePayload with last stored payload proposal ID ,remote chain id , payload, adapter params , values and reason for failure
     * @custom:access Controlled by Access Control Manager
     */
    function execute(
        uint16 remoteChainId_,
        bytes calldata payload_,
        bytes calldata adapterParams_,
        address zroPaymentAddress_
    ) external payable whenNotPaused {
        _ensureAllowed("execute(uint16,bytes,bytes,address)");

        // A zero value will result in a failed message; therefore, a positive value is required to send a message across the chain.
        require(msg.value > 0, "OmnichainProposalSender: value cannot be zero");
        require(payload_.length != 0, "OmnichainProposalSender: empty payload");

        bytes memory trustedRemote = trustedRemoteLookup[remoteChainId_];
        require(trustedRemote.length != 0, "OmnichainProposalSender: destination chain is not a trusted source");
        _validateProposal(remoteChainId_, payload_);
        uint256 _pId = ++proposalCount;
        bytes memory payload = abi.encode(payload_, _pId);

        try
            LZ_ENDPOINT.send{ value: msg.value }(
                remoteChainId_,
                trustedRemote,
                payload,
                payable(msg.sender),
                zroPaymentAddress_,
                adapterParams_
            )
        {
            emit ExecuteRemoteProposal(remoteChainId_, _pId, payload);
        } catch (bytes memory reason) {
            storedExecutionHashes[_pId] = keccak256(abi.encode(remoteChainId_, payload, adapterParams_, msg.value));
            emit StorePayload(_pId, remoteChainId_, payload, adapterParams_, msg.value, reason);
        }
    }

    /**
     * @notice Resends a previously failed message
     * @dev Allows providing more fees if needed. The extra fees will be refunded to the caller
     * @param pId_ The proposal ID to identify a failed message
     * @param remoteChainId_ The LayerZero id of the remote chain
     * @param payload_ The payload to be sent to the remote chain
     * It's computed as follows: payload = abi.encode(abi.encode(targets, values, signatures, calldatas, proposalType), pId)
     * @param adapterParams_ The params used to specify the custom amount of gas required for the execution on the destination
     * @param zroPaymentAddress_ The address of the ZRO token holder who would pay for the transaction.
     * @param originalValue_ The msg.value passed when execute() function was called
     * @custom:event Emits ClearPayload with proposal ID and hash
     * @custom:access Controlled by Access Control Manager
     */
    function retryExecute(
        uint256 pId_,
        uint16 remoteChainId_,
        bytes calldata payload_,
        bytes calldata adapterParams_,
        address zroPaymentAddress_,
        uint256 originalValue_
    ) external payable whenNotPaused nonReentrant {
        _ensureAllowed("retryExecute(uint256,uint16,bytes,bytes,address,uint256)");
        bytes memory trustedRemote = trustedRemoteLookup[remoteChainId_];
        require(trustedRemote.length != 0, "OmnichainProposalSender: destination chain is not a trusted source");
        bytes32 hash = storedExecutionHashes[pId_];
        require(hash != bytes32(0), "OmnichainProposalSender: no stored payload");
        require(payload_.length != 0, "OmnichainProposalSender: empty payload");
        (bytes memory payload, ) = abi.decode(payload_, (bytes, uint256));
        _validateProposal(remoteChainId_, payload);

        require(
            keccak256(abi.encode(remoteChainId_, payload_, adapterParams_, originalValue_)) == hash,
            "OmnichainProposalSender: invalid execution params"
        );

        delete storedExecutionHashes[pId_];

        emit ClearPayload(pId_, hash);

        LZ_ENDPOINT.send{ value: originalValue_ + msg.value }(
            remoteChainId_,
            trustedRemote,
            payload_,
            payable(msg.sender),
            zroPaymentAddress_,
            adapterParams_
        );
    }

    /**
     * @notice Clear previously failed message
     * @param to_ Address of the receiver
     * @param pId_ The proposal ID to identify a failed message
     * @param remoteChainId_ The LayerZero id of the remote chain
     * @param payload_ The payload to be sent to the remote chain
     * It's computed as follows: payload = abi.encode(abi.encode(targets, values, signatures, calldatas, proposalType), pId)
     * @param adapterParams_ The params used to specify the custom amount of gas required for the execution on the destination
     * @param originalValue_ The msg.value passed when execute() function was called
     * @custom:access Only owner
     * @custom:event Emits ClearPayload with proposal ID and hash
     * @custom:event Emits FallbackWithdraw with receiver and amount
     */
    function fallbackWithdraw(
        address to_,
        uint256 pId_,
        uint16 remoteChainId_,
        bytes calldata payload_,
        bytes calldata adapterParams_,
        uint256 originalValue_
    ) external onlyOwner nonReentrant {
        ensureNonzeroAddress(to_);
        require(originalValue_ > 0, "OmnichainProposalSender: invalid native amount");
        require(payload_.length != 0, "OmnichainProposalSender: empty payload");

        bytes32 hash = storedExecutionHashes[pId_];
        require(hash != bytes32(0), "OmnichainProposalSender: no stored payload");

        bytes memory execution = abi.encode(remoteChainId_, payload_, adapterParams_, originalValue_);
        require(keccak256(execution) == hash, "OmnichainProposalSender: invalid execution params");

        delete storedExecutionHashes[pId_];

        emit FallbackWithdraw(to_, originalValue_);
        emit ClearPayload(pId_, hash);

        // Transfer the native to the `to_` address
        (bool sent, ) = to_.call{ value: originalValue_ }("");
        require(sent, "Call failed");
    }

    /**
     * @notice Sets the remote message receiver address
     * @param remoteChainId_ The LayerZero id of a remote chain
     * @param newRemoteAddress_ The address of the contract on the remote chain to receive messages sent by this contract
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits SetTrustedRemoteAddress with remote chain Id and remote address
     */
    function setTrustedRemoteAddress(uint16 remoteChainId_, bytes calldata newRemoteAddress_) external {
        _ensureAllowed("setTrustedRemoteAddress(uint16,bytes)");
        require(remoteChainId_ != 0, "OmnichainProposalSender: chainId must not be zero");
        ensureNonzeroAddress(address(uint160(bytes20(newRemoteAddress_))));
        require(newRemoteAddress_.length == 20, "OmnichainProposalSender: remote address must be 20 bytes long");
        bytes memory oldRemoteAddress = trustedRemoteLookup[remoteChainId_];
        trustedRemoteLookup[remoteChainId_] = abi.encodePacked(newRemoteAddress_, address(this));
        emit SetTrustedRemoteAddress(remoteChainId_, oldRemoteAddress, trustedRemoteLookup[remoteChainId_]);
    }

    /**
     * @notice Sets the configuration of the LayerZero messaging library of the specified version
     * @param version_ Messaging library version
     * @param chainId_ The LayerZero chainId for the pending config change
     * @param configType_ The type of configuration. Every messaging library has its own convention
     * @param config_ The configuration in bytes. It can encode arbitrary content
     * @custom:access Controlled by AccessControlManager
     */
    function setConfig(uint16 version_, uint16 chainId_, uint256 configType_, bytes calldata config_) external {
        _ensureAllowed("setConfig(uint16,uint16,uint256,bytes)");
        LZ_ENDPOINT.setConfig(version_, chainId_, configType_, config_);
    }

    /**
     * @notice Sets the configuration of the LayerZero messaging library of the specified version
     * @param version_ New messaging library version
     * @custom:access Controlled by AccessControlManager
     */
    function setSendVersion(uint16 version_) external {
        _ensureAllowed("setSendVersion(uint16)");
        LZ_ENDPOINT.setSendVersion(version_);
    }

    /**
     * @notice Gets the configuration of the LayerZero messaging library of the specified version
     * @param version_ Messaging library version
     * @param chainId_ The LayerZero chainId
     * @param configType_ Type of configuration. Every messaging library has its own convention
     */
    function getConfig(uint16 version_, uint16 chainId_, uint256 configType_) external view returns (bytes memory) {
        return LZ_ENDPOINT.getConfig(version_, chainId_, address(this), configType_);
    }

    function _validateProposal(uint16 remoteChainId_, bytes memory payload_) internal {
        (
            address[] memory targets,
            uint256[] memory values,
            string[] memory signatures,
            bytes[] memory calldatas,

        ) = abi.decode(payload_, (address[], uint[], string[], bytes[], uint8));
        require(
            targets.length == values.length &&
                targets.length == signatures.length &&
                targets.length == calldatas.length,
            "OmnichainProposalSender: proposal function information arity mismatch"
        );
        _isEligibleToSend(remoteChainId_, targets.length);
    }
}

contracts/Governance/AccessControlledV8..content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";

import "./IAccessControlManagerV8.sol";

/**
 * @title AccessControlledV8
 * @author Venus
 * @notice This contract is helper between access control manager and actual contract. This contract further inherited by other contract (using solidity 0.8.13)
 * to integrate access controlled mechanism. It provides initialise methods and verifying access methods.
 */
abstract contract AccessControlledV8 is Initializable, Ownable2StepUpgradeable {
    /// @notice Access control manager contract
    IAccessControlManagerV8 internal _accessControlManager;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[49] private __gap;

    /// @notice Emitted when access control manager contract address is changed
    event NewAccessControlManager(address oldAccessControlManager, address newAccessControlManager);

    /// @notice Thrown when the action is prohibited by AccessControlManager
    error Unauthorized(address sender, address calledContract, string methodSignature);

    function __AccessControlled_init(address accessControlManager_) internal onlyInitializing {
        __Ownable2Step_init();
        __AccessControlled_init_unchained(accessControlManager_);
    }

    function __AccessControlled_init_unchained(address accessControlManager_) internal onlyInitializing {
        _setAccessControlManager(accessControlManager_);
    }

    /**
     * @notice Sets the address of AccessControlManager
     * @dev Admin function to set address of AccessControlManager
     * @param accessControlManager_ The new address of the AccessControlManager
     * @custom:event Emits NewAccessControlManager event
     * @custom:access Only Governance
     */
    function setAccessControlManager(address accessControlManager_) external onlyOwner {
        _setAccessControlManager(accessControlManager_);
    }

    /**
     * @notice Returns the address of the access control manager contract
     */
    function accessControlManager() external view returns (IAccessControlManagerV8) {
        return _accessControlManager;
    }

    /**
     * @dev Internal function to set address of AccessControlManager
     * @param accessControlManager_ The new address of the AccessControlManager
     */
    function _setAccessControlManager(address accessControlManager_) internal {
        require(address(accessControlManager_) != address(0), "invalid acess control manager address");
        address oldAccessControlManager = address(_accessControlManager);
        _accessControlManager = IAccessControlManagerV8(accessControlManager_);
        emit NewAccessControlManager(oldAccessControlManager, accessControlManager_);
    }

    /**
     * @notice Reverts if the call is not allowed by AccessControlManager
     * @param signature Method signature
     */
    function _checkAccessAllowed(string memory signature) internal view {
        bool isAllowedToCall = _accessControlManager.isAllowedToCall(msg.sender, signature);

        if (!isAllowedToCall) {
            revert Unauthorized(msg.sender, address(this), signature);
        }
    }
}

