// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;
pragma experimental ABIEncoderV2;

/**
 * @title GovernorBravoEvents
 * @author Venus
 * @notice Set of events emitted by the GovernorBravo contracts.
 */
contract GovernorBravoEvents {
    /// @notice An event emitted when a new proposal is created
    event ProposalCreated(
        uint256 id,
        address proposer,
        address[] targets,
        uint[] values,
        string[] signatures,
        bytes[] calldatas,
        uint256 startBlock,
        uint256 endBlock,
        string description,
        uint8 proposalType
    );

    /// @notice An event emitted when a vote has been cast on a proposal
    /// @param voter The address which casted a vote
    /// @param proposalId The proposal id which was voted on
    /// @param support Support value for the vote. 0=against, 1=for, 2=abstain
    /// @param votes Number of votes which were cast by the voter
    /// @param reason The reason given for the vote by the voter
    event VoteCast(address indexed voter, uint256 proposalId, uint8 support, uint256 votes, string reason);

    /// @notice An event emitted when a proposal has been canceled
    event ProposalCanceled(uint256 id);

    /// @notice An event emitted when a proposal has been queued in the Timelock
    event ProposalQueued(uint256 id, uint256 eta);

    /// @notice An event emitted when a proposal has been executed in the Timelock
    event ProposalExecuted(uint256 id);

    /// @notice An event emitted when the voting delay is set
    event VotingDelaySet(uint256 oldVotingDelay, uint256 newVotingDelay);

    /// @notice An event emitted when the voting period is set
    event VotingPeriodSet(uint256 oldVotingPeriod, uint256 newVotingPeriod);

    /// @notice Emitted when implementation is changed
    event NewImplementation(address oldImplementation, address newImplementation);

    /// @notice Emitted when proposal threshold is set
    event ProposalThresholdSet(uint256 oldProposalThreshold, uint256 newProposalThreshold);

    /// @notice Emitted when pendingAdmin is changed
    event NewPendingAdmin(address oldPendingAdmin, address newPendingAdmin);

    /// @notice Emitted when pendingAdmin is accepted, which means admin is updated
    event NewAdmin(address oldAdmin, address newAdmin);

    /// @notice Emitted when the new guardian address is set
    event NewGuardian(address oldGuardian, address newGuardian);

    /// @notice Emitted when the maximum number of operations in one proposal is updated
    event ProposalMaxOperationsUpdated(uint256 oldMaxOperations, uint256 newMaxOperations);

    /// @notice Emitted when a proposer is added to the whitelist
    event WhitelistedProposerAdded(address indexed proposer, GovernorBravoDelegateStorageV2.ProposalType proposalType);

    /// @notice Emitted when a proposer is removed from the whitelist
    event WhitelistedProposerRemoved(
        address indexed proposer,
        GovernorBravoDelegateStorageV2.ProposalType proposalType
    );

    /// @notice Emitted when the new validation params are set
    event SetValidationParams(
        uint256 oldMinVotingPeriod,
        uint256 newMinVotingPeriod,
        uint256 oldmaxVotingPeriod,
        uint256 newmaxVotingPeriod,
        uint256 oldminVotingDelay,
        uint256 newminVotingDelay,
        uint256 oldmaxVotingDelay,
        uint256 newmaxVotingDelay
    );

    /// @notice Emitted when new Proposal configs added
    event SetProposalConfigs(uint256 votingPeriod, uint256 votingDelay, uint256 proposalThreshold);

    /// @notice Error thrown when the caller is not the admin
    error OnlyAdmin();

    /// @notice Error thrown when the contract is already initialized
    error AlreadyInitialized();

    /// @notice Error thrown when the arity of the proposal function parameters are not equal
    error ArityMismatch(string parameterName);

    /// @notice Error thrown when the min voting period is invalid
    error InvalidMinVotingPeriod();

    /// @notice Error thrown when the max voting period is invalid
    error InvalidMaxVotingPeriod();

    /// @notice Error thrown when the min voting delay is invalid
    error InvalidMinVotingDelay();

    /// @notice Error thrown when the max voting delay is invalid
    error InvalidMaxVotingDelay();

    /// @notice Error thrown when the min proposal threshold is invalid
    error InvalidMinProposalThreshold();

    /// @notice Error thrown when the max proposal threshold is invalid
    error InvalidMaxProposalThreshold();

    /// @notice Error thrown when the governor is not active
    error GovernorNotActive();

    /// @notice Error thrown when user has insufficient voting power to execute a command
    error InsufficientVotingPower();

    /// @notice Error thrown when no actions are provided
    error NoActionsProvided();

    /// @notice Error thrown when too many actions are provided
    error TooManyActions();

    /// @notice Error thrown when a proposer has an active or pending proposal
    error OneLiveProposalPerProposer();

    /// @notice Error thrown when a proposal is not active
    error ProposalNotActive();

    /// @notice Error thrown when a proposal has not succeeded
    error ProposalNotSucceeded();

    /// @notice Error thrown when a proposal has not been queued
    error ProposalNotQueued();

    /// @notice Error thrown when a proposal has already been executed
    error ProposalAlreadyExecuted();

    /// @notice Error thrown when a proposal tries to queue identical actions
    error DuplicateAction();

    /// @notice Error thrown when the proposal id is too high (doesn't exist)
    error InvalidProposalId();

    /// @notice Error thrown when the signature is invalid
    error InvalidSignature();

    /// @notice Error thrown when vote type is not correct
    error InvalidVoteType();

    /// @notice Error thrown when user has already voted
    error UserAlreadyVoted();

    /// @notice Error thrown when sender is not pending admin
    error SenderIsNotPendingAdmin();

    /// @notice Error thrown when the proposer is not whitelisted
    error TimelockNotWhitelistedForProposer();
}

/**
 * @title GovernorBravoDelegatorStorage
 * @author Venus
 * @notice Storage layout of the `GovernorBravoDelegator` contract
 */
contract GovernorBravoDelegatorStorage {
    /// @notice Administrator for this contract
    address public admin;

    /// @notice Pending administrator for this contract
    address public pendingAdmin;

    /// @notice Active brains of Governor
    address public implementation;
}

/**
 * @title GovernorBravoDelegateStorageV1
 * @dev For future upgrades, do not change GovernorBravoDelegateStorageV1. Create a new
 * contract which implements GovernorBravoDelegateStorageV1 and following the naming convention
 * GovernorBravoDelegateStorageVX.
 */
contract GovernorBravoDelegateStorageV1 is GovernorBravoDelegatorStorage {
    /// @notice DEPRECATED The delay before voting on a proposal may take place, once proposed, in blocks
    uint256 public votingDelay;

    /// @notice DEPRECATED The duration of voting on a proposal, in blocks
    uint256 public votingPeriod;

    /// @notice DEPRECATED The number of votes required in order for a voter to become a proposer
    uint256 public proposalThreshold;

    /// @notice Initial proposal id set at become
    uint256 public initialProposalId;

    /// @notice The total number of proposals
    uint256 public proposalCount;

    /// @notice The address of the Venus Protocol Timelock
    TimelockInterface public timelock;

    /// @notice The address of the Venus governance token
    XvsVaultInterface public xvsVault;

    /// @notice The official record of all proposals ever proposed
    mapping(uint256 => Proposal) public proposals;

    /// @notice The latest proposal for each proposer
    mapping(address => uint) public latestProposalIds;

    struct Proposal {
        /// @notice Unique id for looking up a proposal
        uint256 id;
        /// @notice Creator of the proposal
        address proposer;
        /// @notice The timestamp that the proposal will be available for execution, set once the vote succeeds
        uint256 eta;
        /// @notice the ordered list of target addresses for calls to be made
        address[] targets;
        /// @notice The ordered list of values (i.e. msg.value) to be passed to the calls to be made
        uint256[] values;
        /// @notice The ordered list of function signatures to be called
        string[] signatures;
        /// @notice The ordered list of calldata to be passed to each call
        bytes[] calldatas;
        /// @notice The block at which voting begins: holders must delegate their votes prior to this block
        uint256 startBlock;
        /// @notice The block at which voting ends: votes must be cast prior to this block
        uint256 endBlock;
        /// @notice Current number of votes in favor of this proposal
        uint256 forVotes;
        /// @notice Current number of votes in opposition to this proposal
        uint256 againstVotes;
        /// @notice Current number of votes for abstaining for this proposal
        uint256 abstainVotes;
        /// @notice Flag marking whether the proposal has been canceled
        bool canceled;
        /// @notice Flag marking whether the proposal has been executed
        bool executed;
        /// @notice Receipts of ballots for the entire set of voters
        mapping(address => Receipt) receipts;
        /// @notice The type of the proposal
        uint8 proposalType;
    }

    /// @notice Ballot receipt record for a voter
    struct Receipt {
        /// @notice Whether or not a vote has been cast
        bool hasVoted;
        /// @notice Whether or not the voter supports the proposal or abstains
        uint8 support;
        /// @notice The number of votes the voter had, which were cast
        uint96 votes;
    }

    /// @notice Possible states that a proposal may be in
    enum ProposalState {
        Pending,
        Active,
        Canceled,
        Defeated,
        Succeeded,
        Queued,
        Expired,
        Executed
    }

    /// @notice The maximum number of actions that can be included in a proposal
    uint256 public proposalMaxOperations;

    /// @notice A privileged role that can cancel any proposal
    address public guardian;
}

/**
 * @title GovernorBravoDelegateStorageV2
 * @dev For future upgrades, do not change GovernorBravoDelegateStorageV1. Create a new
 * contract which implements GovernorBravoDelegateStorageV2 and following the naming convention
 * GovernorBravoDelegateStorageVX.
 */
contract GovernorBravoDelegateStorageV2 is GovernorBravoDelegateStorageV1 {
    enum ProposalType {
        NORMAL,
        FASTTRACK,
        CRITICAL
    }

    struct ProposalConfig {
        /// @notice The delay before voting on a proposal may take place, once proposed, in blocks
        uint256 votingDelay;
        /// @notice The duration of voting on a proposal, in blocks
        uint256 votingPeriod;
        /// @notice The number of votes required in order for a voter to become a proposer
        uint256 proposalThreshold;
    }

    /// @notice mapping containing configuration for each proposal type
    mapping(uint256 => ProposalConfig) public proposalConfigs;

    /// @notice mapping containing Timelock addresses for each proposal type
    mapping(uint256 => TimelockInterface) public proposalTimelocks;
}

/**
 * @title GovernorBravoDelegateStorageV3
 * @dev For future upgrades, do not change GovernorBravoDelegateStorageV3. Create a new
 * contract which implements GovernorBravoDelegateStorageV3 and following the naming convention
 * GovernorBravoDelegateStorageVX.
 */
contract GovernorBravoDelegateStorageV3 is GovernorBravoDelegateStorageV2 {
    struct ValidationParams {
        uint256 minVotingPeriod;
        uint256 maxVotingPeriod;
        uint256 minVotingDelay;
        uint256 maxVotingDelay;
    }
    /// @notice Stores the current minimum and maximum values of voting delay and voting period
    ValidationParams public validationParams;
}

/**
 * @title GovernorBravoDelegateStorageV4
 * @dev For future upgrades, do not change GovernorBravoDelegateStorageV4. Create a new
 * contract which implements GovernorBravoDelegateStorageV4 and following the naming convention
 * GovernorBravoDelegateStorageVX.
 */
contract GovernorBravoDelegateStorageV4 is GovernorBravoDelegateStorageV3 {
    /// @notice Mapping to store whitelisted proposers and the timelock they are authorized to use
    mapping(address => mapping(GovernorBravoDelegateStorageV2.ProposalType => bool)) public whitelistedProposers;
}

interface IGovernorBravoDelegate {
    function propose(
        address[] memory targets,
        uint256[] memory values,
        string[] memory signatures,
        bytes[] memory calldatas,
        string memory description,
        GovernorBravoDelegateStorageV2.ProposalType proposalType
    ) external returns (uint256);

    function queue(uint256 proposalId) external;

    function whitelistProposer(address proposer, GovernorBravoDelegateStorageV2.ProposalType proposalType) external;

    function removeWhitelistedProposer(address proposer) external;

    function execute(uint256 proposalId) external;

    function cancel(uint256 proposalId) external;

    function getReceipt(
        uint256 proposalId,
        address voter
    ) external view returns (GovernorBravoDelegateStorageV2.Receipt memory);

    function state(uint256 proposalId) external view returns (GovernorBravoDelegateStorageV2.ProposalState);

    function castVote(uint256 proposalId, uint8 support) external;

    function castVoteWithReason(uint256 proposalId, uint8 support, string calldata reason) external;

    function castVoteBySig(uint256 proposalId, uint8 support, uint8 v, bytes32 r, bytes32 s) external;

    function _setGuardian(address newGuardian) external;

    function _initiate(address governorAlpha) external;

    function _setProposalMaxOperations(uint256 proposalMaxOperations_) external;

    function _setPendingAdmin(address newPendingAdmin) external;

    function _acceptAdmin() external;
}

/**
 * @title TimelockInterface
 * @author Venus
 * @notice Interface implemented by the Timelock contract.
 */
interface TimelockInterface {
    function delay() external view returns (uint);

    function GRACE_PERIOD() external view returns (uint);

    function acceptAdmin() external;

    function queuedTransactions(bytes32 hash) external view returns (bool);

    function queueTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) external returns (bytes32);

    function cancelTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) external;

    function executeTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) external payable returns (bytes memory);
}

interface XvsVaultInterface {
    function getPriorVotes(address account, uint256 blockNumber) external view returns (uint96);
}

interface GovernorAlphaInterface {
    /// @notice The total number of proposals
    function proposalCount() external returns (uint);
}

contracts/Governance/TimelockV8.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";

/**
 * @title TimelockV8
 * @author Venus
 * @notice The Timelock contract using solidity V8.
 * This contract also differs from the original timelock because it has a virtual function to get minimum delays
 * and allow test deployments to override the value.
 */
contract TimelockV8 {
    /// @notice Required period to execute a proposal transaction
    uint256 private constant DEFAULT_GRACE_PERIOD = 14 days;

    /// @notice Minimum amount of time a proposal transaction must be queued
    uint256 private constant DEFAULT_MINIMUM_DELAY = 1 hours;

    /// @notice Maximum amount of time a proposal transaction must be queued
    uint256 private constant DEFAULT_MAXIMUM_DELAY = 30 days;

    /// @notice Timelock admin authorized to queue and execute transactions
    address public admin;

    /// @notice Account proposed as the next admin
    address public pendingAdmin;

    /// @notice Period for a proposal transaction to be queued
    uint256 public delay;

    /// @notice Mapping of queued transactions
    mapping(bytes32 => bool) public queuedTransactions;

    /// @notice Event emitted when a new admin is accepted
    event NewAdmin(address indexed oldAdmin, address indexed newAdmin);

    /// @notice Event emitted when a new admin is proposed
    event NewPendingAdmin(address indexed newPendingAdmin);

    /// @notice Event emitted when a new delay is proposed
    event NewDelay(uint256 indexed oldDelay, uint256 indexed newDelay);

    /// @notice Event emitted when a proposal transaction has been cancelled
    event CancelTransaction(
        bytes32 indexed txHash,
        address indexed target,
        uint256 value,
        string signature,
        bytes data,
        uint256 eta
    );

    /// @notice Event emitted when a proposal transaction has been executed
    event ExecuteTransaction(
        bytes32 indexed txHash,
        address indexed target,
        uint256 value,
        string signature,
        bytes data,
        uint256 eta
    );

    /// @notice Event emitted when a proposal transaction has been queued
    event QueueTransaction(
        bytes32 indexed txHash,
        address indexed target,
        uint256 value,
        string signature,
        bytes data,
        uint256 eta
    );

    constructor(address admin_, uint256 delay_) {
        require(delay_ >= MINIMUM_DELAY(), "Timelock::constructor: Delay must exceed minimum delay.");
        require(delay_ <= MAXIMUM_DELAY(), "Timelock::setDelay: Delay must not exceed maximum delay.");
        ensureNonzeroAddress(admin_);

        admin = admin_;
        delay = delay_;
    }

    fallback() external payable {}

    /**
     * @notice Setter for the transaction queue delay
     * @param delay_ The new delay period for the transaction queue
     * @custom:access Sender must be Timelock itself
     * @custom:event Emit NewDelay with old and new delay
     */
    function setDelay(uint256 delay_) public {
        require(msg.sender == address(this), "Timelock::setDelay: Call must come from Timelock.");
        require(delay_ >= MINIMUM_DELAY(), "Timelock::setDelay: Delay must exceed minimum delay.");
        require(delay_ <= MAXIMUM_DELAY(), "Timelock::setDelay: Delay must not exceed maximum delay.");
        emit NewDelay(delay, delay_);
        delay = delay_;
    }

    /**
     * @notice Return grace period
     * @return The duration of the grace period, specified as a uint256 value.
     */
    function GRACE_PERIOD() public view virtual returns (uint256) {
        return DEFAULT_GRACE_PERIOD;
    }

    /**
     * @notice Return required minimum delay
     * @return Minimum delay
     */
    function MINIMUM_DELAY() public view virtual returns (uint256) {
        return DEFAULT_MINIMUM_DELAY;
    }

    /**
     * @notice Return required maximum delay
     * @return Maximum delay
     */
    function MAXIMUM_DELAY() public view virtual returns (uint256) {
        return DEFAULT_MAXIMUM_DELAY;
    }

    /**
     * @notice Method for accepting a proposed admin
     * @custom:access Sender must be pending admin
     * @custom:event Emit NewAdmin with old and new admin
     */
    function acceptAdmin() public {
        require(msg.sender == pendingAdmin, "Timelock::acceptAdmin: Call must come from pendingAdmin.");
        emit NewAdmin(admin, msg.sender);
        admin = msg.sender;
        pendingAdmin = address(0);
    }

    /**
     * @notice Method to propose a new admin authorized to call timelock functions. This should be the Governor Contract
     * @param pendingAdmin_ Address of the proposed admin
     * @custom:access Sender must be Timelock contract itself or admin
     * @custom:event Emit NewPendingAdmin with new pending admin
     */
    function setPendingAdmin(address pendingAdmin_) public {
        require(
            msg.sender == address(this) || msg.sender == admin,
            "Timelock::setPendingAdmin: Call must come from Timelock."
        );
        ensureNonzeroAddress(pendingAdmin_);
        pendingAdmin = pendingAdmin_;

        emit NewPendingAdmin(pendingAdmin);
    }

    /**
     * @notice Called for each action when queuing a proposal
     * @param target Address of the contract with the method to be called
     * @param value Native token amount sent with the transaction
     * @param signature Signature of the function to be called
     * @param data Arguments to be passed to the function when called
     * @param eta Timestamp after which the transaction can be executed
     * @return Hash of the queued transaction
     * @custom:access Sender must be admin
     * @custom:event Emit QueueTransaction
     */
    function queueTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) public returns (bytes32) {
        require(msg.sender == admin, "Timelock::queueTransaction: Call must come from admin.");
        require(
            eta >= getBlockTimestamp() + delay,
            "Timelock::queueTransaction: Estimated execution block must satisfy delay."
        );

        bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
        require(!queuedTransactions[txHash], "Timelock::queueTransaction: transaction already queued.");
        queuedTransactions[txHash] = true;

        emit QueueTransaction(txHash, target, value, signature, data, eta);
        return txHash;
    }

    /**
     * @notice Called to cancel a queued transaction
     * @param target Address of the contract with the method to be called
     * @param value Native token amount sent with the transaction
     * @param signature Signature of the function to be called
     * @param data Arguments to be passed to the function when called
     * @param eta Timestamp after which the transaction can be executed
     * @custom:access Sender must be admin
     * @custom:event Emit CancelTransaction
     */
    function cancelTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) public {
        require(msg.sender == admin, "Timelock::cancelTransaction: Call must come from admin.");

        bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
        require(queuedTransactions[txHash], "Timelock::cancelTransaction: transaction is not queued yet.");
        delete (queuedTransactions[txHash]);

        emit CancelTransaction(txHash, target, value, signature, data, eta);
    }

    /**
     * @notice Called to execute a queued transaction
     * @param target Address of the contract with the method to be called
     * @param value Native token amount sent with the transaction
     * @param signature Signature of the function to be called
     * @param data Arguments to be passed to the function when called
     * @param eta Timestamp after which the transaction can be executed
     * @return Result of function call
     * @custom:access Sender must be admin
     * @custom:event Emit ExecuteTransaction
     */
    function executeTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) public returns (bytes memory) {
        require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");

        bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
        require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
        require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
        require(getBlockTimestamp() <= eta + GRACE_PERIOD(), "Timelock::executeTransaction: Transaction is stale.");

        delete (queuedTransactions[txHash]);

        bytes memory callData;

        if (bytes(signature).length == 0) {
            callData = data;
        } else {
            callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
        }

        // solium-disable-next-line security/no-call-value
        (bool success, bytes memory returnData) = target.call{ value: value }(callData);
        require(success, "Timelock::executeTransaction: Transaction execution reverted.");

        emit ExecuteTransaction(txHash, target, value, signature, data, eta);

        return returnData;
    }

    /**
     * @notice Returns the current block timestamp
     * @return The current block timestamp
     */
    function getBlockTimestamp() internal view returns (uint256) {
        // solium-disable-next-line security/no-block-members
        return block.timestamp;
    }
}

