// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { Strings } from "@openzeppelin/contracts/utils/Strings.sol";
import { IVToken } from "../interfaces/IVToken.sol";
import { ICorePoolComptroller } from "../interfaces/ICorePoolComptroller.sol";
import { IIsolatedPoolsComptroller } from "../interfaces/IIsolatedPoolsComptroller.sol";
import { IRiskStewardReceiver } from "../interfaces/IRiskStewardReceiver.sol";
import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { IRiskSteward } from "../interfaces/IRiskSteward.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";

/**
 * @title MarketCapsRiskSteward
 * @author Venus
 * @notice Contract that can update supply and borrow caps received from RiskStewardReceiver. Requires that the update is within the max delta.
 * Expects the new value to be an encoded uint256 value of un padded bytes.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract MarketCapsRiskSteward is IRiskSteward, AccessControlledV8 {
    /// @dev Max basis points i.e., 100%
    uint256 private constant MAX_BPS = 10000;

    /**
     * @notice Address of the CorePoolComptroller used for selecting the correct comptroller abi
     */
    ICorePoolComptroller public immutable CORE_POOL_COMPTROLLER;

    /**
     * @notice Address of the RiskStewardReceiver used to validate incoming updates
     */
    IRiskStewardReceiver public immutable RISK_STEWARD_RECEIVER;

    /**
     * @notice The max delta bps for the update relative to the current value
     */
    uint256 public maxDeltaBps;
    /**
     * @notice The update type for supply caps
     */
    string public constant SUPPLY_CAP = "supplyCap";

    /**
     * @notice The update type for borrow caps
     */
    string public constant BORROW_CAP = "borrowCap";

    /**
     * @notice The debounce period for updates in seconds
     */
    uint256 public debouncePeriod;

    /**
     * @notice Mapping of market and update type to last update timestamp. Used for debouncing updates.
     */
    mapping(bytes marketUpdateType => uint256) public lastProcessedTime;

    /**
     * @notice Mapping of processed updates. Used to prevent re-execution
     */
    mapping(uint256 updateId => bool) public processedUpdates;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[47] private __gap;

    /**
     * @notice Emitted when a supply cap is updated
     */
    event SupplyCapUpdated(address indexed market, uint256 indexed newSupplyCap);

    /**
     * @notice Emitted when a borrow cap is updated
     */
    event BorrowCapUpdated(address indexed market, uint256 indexed newBorrowCap);

    /**
     * @notice Emitted when the max delta bps is updated
     */
    event MaxDeltaBpsUpdated(uint256 oldMaxDeltaBps, uint256 indexed newMaxDeltaBps);

    /**
     * @notice Emitted when the debounce period is updated
     */
    event DebouncePeriodUpdated(uint256 oldDebouncePeriod, uint256 newDebouncePeriod);

    /**
     * @notice Thrown when a maxDeltaBps value of 0 is set
     */
    error InvalidMaxDeltaBps();

    /**
     * @notice Thrown when a debounce period of 0 is set
     */
    error InvalidDebouncePeriod();

    /**
     * @notice Thrown when an updateType that is not supported is operated on
     */
    error UnsupportedUpdateType(uint256 updateId);

    /**
     * @notice Thrown when the new value of an update is out of range
     */
    error UpdateNotInRange(uint256 updateId);

    /**
     * @notice Thrown when the debounce period hasn't passed for applying an update to a specific market/ update type
     */
    error UpdateTooFrequent();

    /**
     * @dev Sets the immutable CorePoolComptroller and RiskStewardReceiver addresses and disables initializers
     * @param riskStewardReceiver_ The address of the RiskStewardReceiver
     * @param corePoolComptroller_ The address of the corePoolComptroller
     * @custom:error Throws ZeroAddressNotAllowed if the CorePoolComptroller or RiskStewardReceiver addresses are zero
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(address riskStewardReceiver_, address corePoolComptroller_) {
        ensureNonzeroAddress(riskStewardReceiver_);
        ensureNonzeroAddress(corePoolComptroller_);
        RISK_STEWARD_RECEIVER = IRiskStewardReceiver(riskStewardReceiver_);
        CORE_POOL_COMPTROLLER = ICorePoolComptroller(corePoolComptroller_);
        _disableInitializers();
    }

    /**
     * @dev Initializes the contract as ownable, access controlled, and pausable. Sets the max delta bps initial value.
     * @param accessControlManager_ The address of the access control manager
     * @param maxDeltaBps_ The max detla bps
     * @param debouncePeriod_ The debounce period
     * @custom:error Throws InvalidMaxDeltaBps if the max delta bps is 0 or greater than MAX_BPS
     */
    function initialize(
        address accessControlManager_,
        uint256 maxDeltaBps_,
        uint256 debouncePeriod_
    ) external initializer {
        __AccessControlled_init(accessControlManager_);
        if (maxDeltaBps_ == 0 || maxDeltaBps_ > MAX_BPS) {
            revert InvalidMaxDeltaBps();
        }
        maxDeltaBps = maxDeltaBps_;

        if (debouncePeriod_ == 0 || debouncePeriod_ <= RISK_STEWARD_RECEIVER.UPDATE_EXPIRATION_TIME()) {
            revert InvalidDebouncePeriod();
        }
        debouncePeriod = debouncePeriod_;
    }

    /**
     * @notice Sets the max delta bps
     * @param maxDeltaBps_ The new max delta bps
     * @custom:event Emits MaxDeltaBpsUpdated with the old and new max delta bps
     * @custom:error InvalidMaxDeltaBps if the max delta bps is 0 or greater than MAX_BPS
     * @custom:access Controlled by AccessControlManager
     */
    function setMaxDeltaBps(uint256 maxDeltaBps_) external {
        _checkAccessAllowed("setMaxDeltaBps(uint256)");
        if (maxDeltaBps_ == 0 || maxDeltaBps_ > MAX_BPS) {
            revert InvalidMaxDeltaBps();
        }
        emit MaxDeltaBpsUpdated(maxDeltaBps, maxDeltaBps_);
        maxDeltaBps = maxDeltaBps_;
    }

    /**
     * @notice Sets the debounce period
     * @param debouncePeriod_ The new debounce period
     * @custom:event Emits DebouncePeriodUpdated with the old and new debounce period
     * @custom:error InvalidDebouncePeriod if the debounce period is 0 or less than the RiskStewardReceiver's UPDATE_EXPIRATION_TIME
     * @custom:access Controlled by AccessControlManager
     */
    function setDebouncePeriod(uint256 debouncePeriod_) external {
        _checkAccessAllowed("setDebouncePeriod(uint256)");
        if (debouncePeriod_ == 0 || debouncePeriod_ <= RISK_STEWARD_RECEIVER.UPDATE_EXPIRATION_TIME()) {
            revert InvalidDebouncePeriod();
        }
        emit DebouncePeriodUpdated(debouncePeriod, debouncePeriod_);
        debouncePeriod = debouncePeriod_;
    }

    /**
     * @notice Processes a market cap update from the RiskStewardReceiver.
     * Validates that the update is within range and then directly update the market supply or borrow cap on the market's comptroller.
     * @param updateId The ID of the update
     * @param newValue The new supply cap value
     * @param updateType The type of update
     * @param market The market to update the supply cap for
     * @custom:error UnsupportedUpdateType Thrown if the update type is not supported
     * @custom:error UpdateNotInRange Thrown if the update is not within the allowed range
     * @custom:event Emits SupplyCapUpdated or BorrowCapUpdated depending on the update with the market and new cap
     * @custom:access Controlled by AccessControlManager
     */
    function processUpdate(uint256 updateId, bytes memory newValue, string memory updateType, address market) external {
        _checkAccessAllowed("processUpdate(uint256,bytes,string,address)");
        if (processedUpdates[updateId]) {
            revert("Update already processed");
        }
        processedUpdates[updateId] = true;
        if (Strings.equal(updateType, SUPPLY_CAP)) {
            _processSupplyCapUpdate(updateId, newValue, updateType, market);
        } else if (Strings.equal(updateType, BORROW_CAP)) {
            _processBorrowCapUpdate(updateId, newValue, updateType, market);
        } else {
            revert UnsupportedUpdateType(updateId);
        }
    }

    /**
     * @notice Updates the supply cap for the given market.
     * @param comptroller The comptroller to update the supply cap for
     * @param market The market to update the supply cap for
     * @param newValue The new supply cap value
     * @custom:event Emits SupplyCapUpdated with the market and new supply cap
     */
    function _updateSupplyCaps(address comptroller, address market, uint256 newValue) internal {
        address[] memory newSupplyCapMarkets = new address[](1);
        newSupplyCapMarkets[0] = market;
        uint256[] memory newSupplyCaps = new uint256[](1);
        newSupplyCaps[0] = newValue;

        if (comptroller == address(CORE_POOL_COMPTROLLER)) {
            ICorePoolComptroller(comptroller)._setMarketSupplyCaps(newSupplyCapMarkets, newSupplyCaps);
        } else {
            IIsolatedPoolsComptroller(comptroller).setMarketSupplyCaps(newSupplyCapMarkets, newSupplyCaps);
        }
        emit SupplyCapUpdated(market, newSupplyCaps[0]);
    }

    /**
     * @notice Updates the borrow cap for the given market.
     * @param comptroller The comptroller to update the borrow cap for
     * @param market The market to update the borrow cap for
     * @param newValue The new borrow cap value
     * @custom:event Emits BorrowCapUpdated with the market and new borrow cap
     */
    function _updateBorrowCaps(address comptroller, address market, uint256 newValue) internal {
        address[] memory newBorrowCapMarkets = new address[](1);
        newBorrowCapMarkets[0] = market;
        uint256[] memory newBorrowCaps = new uint256[](1);
        newBorrowCaps[0] = newValue;

        if (comptroller == address(CORE_POOL_COMPTROLLER)) {
            ICorePoolComptroller(comptroller)._setMarketBorrowCaps(newBorrowCapMarkets, newBorrowCaps);
        } else {
            IIsolatedPoolsComptroller(comptroller).setMarketBorrowCaps(newBorrowCapMarkets, newBorrowCaps);
        }
        emit BorrowCapUpdated(market, newBorrowCaps[0]);
    }

    /**
     * @notice Validates the new supply cap and if valid, updates the supply cap for the given market.
     * @param updateId The ID of the update
     * @param newValue The new supply cap value
     * @param updateType The type of update
     * @param market The market to update the supply cap for
     * @custom:event Emits SupplyCapUpdated with the market and new supply cap
     * @custom:error UpdateNotInRange if the update is not within the allowed range
     */
    function _processSupplyCapUpdate(
        uint256 updateId,
        bytes memory newValue,
        string memory updateType,
        address market
    ) internal {
        uint256 newCap = _decodeBytesToUint256(newValue);
        address comptroller = IVToken(market).comptroller();

        _validateSupplyCapUpdate(comptroller, market, updateId, newCap);

        _updateSupplyCaps(comptroller, market, newCap);

        lastProcessedTime[_getMarketUpdateTypeKey(market, updateType)] = block.timestamp;
    }

    /**
     * @notice Validates the new borrow cap and if valid, updates the borrow cap for the given market.
     * @param updateId The ID of the update
     * @param newValue The new borrow cap value
     * @param updateType The type of update
     * @param market The market to update the borrow cap for
     * @custom:event Emits BorrowCapUpdated with the market and new borrow cap
     * @custom:error UpdateNotInRange if the update is not within the allowed range
     */
    function _processBorrowCapUpdate(
        uint256 updateId,
        bytes memory newValue,
        string memory updateType,
        address market
    ) internal {
        uint256 newCap = _decodeBytesToUint256(newValue);
        address comptroller = IVToken(market).comptroller();
        _validateBorrowCapUpdate(comptroller, market, updateId, newCap);
        _updateBorrowCaps(comptroller, market, newCap);
        lastProcessedTime[_getMarketUpdateTypeKey(market, updateType)] = block.timestamp;
    }

    /**
     * @notice Decodes the additional data from the SupplyCap and BorrowCap RiskParameterUpdates
     * @param additionalData The additional data to decode
     * @return underlying The underlying asset address
     * @return destChainId The destination chain ID
     */
    function decodeAdditionalData(bytes calldata additionalData) external pure returns (address, uint32) {
        (address underlying, uint32 destChainId) = abi.decode(additionalData, (address, uint32));
        return (underlying, destChainId);
    }

    /**
     * @notice Packs the new value into a bytes memory
     * @param data The un-padded bytes to decode
     * @return bytes memory The packed bytes
     */
    function packNewValue(bytes memory data) public pure returns (bytes memory) {
        return abi.encodePacked(new bytes(32 - data.length), data);
    }

    /**
     * @notice Checks that the new supply cap is within the allowed range of the current supply cap.
     * @param comptroller The comptroller of the market
     * @param market The market whose supply cap is being updated
     * @param updateId The ID of the update
     * @param newCap The new market cap value to validate
     * @custom:error UpdateNotInRange if the update is not within the allowed range
     */
    function _validateSupplyCapUpdate(
        address comptroller,
        address market,
        uint256 updateId,
        uint256 newCap
    ) internal view {
        uint256 currentSupplyCap = IIsolatedPoolsComptroller(comptroller).supplyCaps(address(market));
        _verifyUpdate(market, updateId, SUPPLY_CAP, currentSupplyCap, newCap);
    }

    /**
     * @notice Checks that the new borrow cap is within the allowed range of the current borrow cap.
     * @param comptroller The comptroller of the market
     * @param market The market whose borrow cap is being updated
     * @param updateId The ID of the update
     * @param newCap The new market cap value to validate
     * @custom:error UpdateNotInRange if the update is not within the allowed range
     */
    function _validateBorrowCapUpdate(
        address comptroller,
        address market,
        uint256 updateId,
        uint256 newCap
    ) internal view {
        uint256 currentBorrowCap = IIsolatedPoolsComptroller(comptroller).borrowCaps(address(market));
        _verifyUpdate(market, updateId, BORROW_CAP, currentBorrowCap, newCap);
    }

    /**
     * @notice Verifies that the update is not too frequent and within the allowed range
     * @param market The market whose update is being verified
     * @param updateId The ID of the update
     * @param updateType The type of update being verified
     * @param previousValue The previous value of the update
     * @param newValue The new value of the update
     * @custom:error UpdateTooFrequent if the update is too frequent
     * @custom:error UpdateNotInRange if the update is not within the allowed range
     */
    function _verifyUpdate(
        address market,
        uint256 updateId,
        string memory updateType,
        uint256 previousValue,
        uint256 newValue
    ) internal view {
        if (block.timestamp - lastProcessedTime[_getMarketUpdateTypeKey(market, updateType)] < debouncePeriod) {
            revert UpdateTooFrequent();
        }
        _updateWithinAllowedRange(updateId, previousValue, newValue);
    }

    /**
     * @notice Ensures the risk param update is within the allowed range.
     * If the previous value is 0, this means the market is not yet supported or disabled and setting a new value is not allowed.
     * @param previousValue current risk param value
     * @param newValue new updated risk param value
     * @custom:error UpdateNotInRange if the update is not within the allowed range
     */
    function _updateWithinAllowedRange(uint256 updateId, uint256 previousValue, uint256 newValue) internal view {
        uint256 diff = newValue > previousValue ? newValue - previousValue : previousValue - newValue;

        uint256 maxDiff = (maxDeltaBps * previousValue) / MAX_BPS;

        if (diff > maxDiff) {
            revert UpdateNotInRange(updateId);
        }
    }

    /**
     * @notice Decodes un-padded bytes to a uint256
     * @param data The un-padded bytes to decode
     * @return uint256 The decoded uint256
     */
    function _decodeBytesToUint256(bytes memory data) internal pure returns (uint256) {
        return abi.decode(packNewValue(data), (uint256));
    }

    /**
     * @dev Encodes the market and update type into a bytes key to be used with the last processed time mapping
     */
    function _getMarketUpdateTypeKey(address market, string memory updateType) internal pure returns (bytes memory) {
        return abi.encodePacked(market, updateType);
    }

    /**
     * @dev Disabling renounceOwnership function.
     */
    function renounceOwnership() public pure override {
        revert("renounceOwnership() is not allowed");
    }
}

contracts/RiskSteward/RiskStewardDestina.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { RiskParameterUpdate } from "../interfaces/IRiskOracle.sol";
import { RiskParamConfig } from "../interfaces/IRiskStewardReceiver.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { RiskStewardReceiverBase } from "./RiskStewardReceiverBase.sol";
import { OApp, Origin } from "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";

/**
 * @title RiskStewardReceiverDestination
 * @author Venus
 * @notice Contract that can read received updates from the RiskStewardReceiver and process them.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract RiskStewardDestinationReceiver is OApp, RiskStewardReceiverBase {
    enum UPDATE_STATUS {
        NONE,
        RECEIVED,
        PROCESSED,
        CONFIG_NOT_ACTIVE,
        EXPIRED,
        CANCELLED,
        FAILED
    }
    /**
     * @notice Time before a submitted update is considered stale
     */
    uint256 public constant REMOTE_UPDATE_EXPIRATION_TIME = 2 days;

    /**
     * @notice Required delay before
     */

    uint256 public remoteDelay = 6 hours;

    /**
     * @notice Address of guardian, who can cancel the update, if required
     */
    address public guardian;

    /**
     * @notice Mapping of processed updates. Used to prevent re-execution
     */
    mapping(uint256 updateId => UPDATE_STATUS) public processedUpdates;

    /**
     * @notice Mapping of received timestamp of update correspond to update id
     */

    mapping(uint256 updateId => uint256 remoteTimestamp) public remoteUpdateTimestamps;

    /**
     * @notice update associated with its ID
     */
    mapping(uint256 updateId => RiskParameterUpdate) public update;

    /**
     * @notice Emitted when applying an update fails to validate or execute
     */
    event RiskParameterUpdateFailed(uint256 indexed updateId, UPDATE_STATUS indexed error);

    /**
     * @notice Emitted when the remote delay is updated
     */
    event SetRemoteDelay(uint256 indexed oldDelay, uint256 indexed newDelay);

    /**
     * @notice Emitted when a risk parameter update is canceled
     */

    event CancelUpdate(uint256 indexed updateId);

    /**
     * @notice Emitted when the guardian address updated
     */
    event SetGuardian(address prevGuardian, address newGuardian);

    /**
     * @notice Emitted when update is received from source chain
     */
    event UpdateReceived(uint256 indexed updateId);

    /**
     * @notice Thrown when update not received from src chain
     */
    error UpdateNotReceived(uint256 updateId);

    /**
     * @notice Thrown when a caller tries to perform an action without the required permissions
     */
    error Unauthorized();

    constructor(address endpoint_, address owner_, address guardian_) OApp(endpoint_, owner_) {
        ensureNonzeroAddress(guardian_);
        guardian = guardian_;
    }

    /**
     * @notice Sets a new delay required before a remote update can be processed
     * @param newDelay The new delay duration in seconds Must be greater than zero
     * @custom:access Only owner
     * @custom:event Emitted SetRemoteDelay with previous and new delay
     */
    function setRemoteDelay(uint256 newDelay) external onlyOwner {
        require(newDelay > 0, "Delay must be greater than 0");
        emit SetRemoteDelay(remoteDelay, newDelay);
        remoteDelay = newDelay;
    }

    /**
     * @notice Updates the guardian address responsible for managing certain administrative functions
     * @dev Callable by the current owner or the current guardian New address must be non-zero
     * @param newGuardian The address of the new guardian
     * @custom:event Emitted SetGuardian with previous and new guardian
     */
    function setGuardian(address newGuardian) external {
        if (msg.sender != guardian && msg.sender != owner()) {
            revert Unauthorized();
        }

        ensureNonzeroAddress(newGuardian);
        emit SetGuardian(guardian, newGuardian);
        guardian = newGuardian;
    }

    /**
     * @notice Processes a stored update from the RiskStewardReceiver. First validates that the update has not be processed, the config is active, and is not expired.
     *         If the update is valid then it is executed, otherwise an update failed error is emitted.
     * @param updateId The ID of the update
     * @custom:access This function can be called by anyone
     */
    function processStoredUpdate(uint256 updateId) external whenNotPaused {
        require(block.timestamp > remoteUpdateTimestamps[updateId] + remoteDelay, "Delay has to be surpassed");
        RiskParameterUpdate memory _update = update[updateId];
        UPDATE_STATUS error = _validateUpdateStatus(updateId, _update.updateType, remoteUpdateTimestamps[updateId]);
        if (error == UPDATE_STATUS.NONE) {
            _executeUpdate(updateId, _update.newValue, _update.updateType, _update.market);
        } else {
            processedUpdates[updateId] = error;
            emit RiskParameterUpdateFailed(updateId, error);
        }
    }

    /**
     * @notice Processes an update from the RiskStewardReceiver. First validates that the update has not be processed, the config is active, and is not expired.
     *         If the update is valid then it is executed, otherwise an update failed error is emitted.
     * @param updateId The ID of the update
     * @param newValue The new value of the update
     * @param updateType The type of update
     * @param market The market of the update
     * @param timestamp The timestamp of the update
     * @custom:access This function should only be callable by timelocks that are trusted to receive cross chain messages
     */
    function processUpdate(
        uint256 updateId,
        bytes calldata newValue,
        string calldata updateType,
        address market,
        uint256 timestamp
    ) external onlyOwner whenNotPaused {
        UPDATE_STATUS error = _validateUpdateStatus(updateId, updateType, timestamp);
        if (error == UPDATE_STATUS.NONE) {
            _executeUpdate(updateId, newValue, updateType, market);
        } else {
            processedUpdates[updateId] = error;
            emit RiskParameterUpdateFailed(updateId, error);
        }
    }

    /**
     * @notice Cancels a pending risk parameter update
     * @param updateId The ID of the update to be canceled
     * @dev Can only be called by the guardian. The update must be in RECEIVED status
     * @custom:event Emitted CancelUpdate with updateId
     */
    function cancelUpdate(uint256 updateId) external {
        if (msg.sender != guardian) {
            revert Unauthorized();
        }
        require(processedUpdates[updateId] == UPDATE_STATUS.RECEIVED, "Status not compatible");
        emit CancelUpdate(updateId);
        processedUpdates[updateId] = UPDATE_STATUS.CANCELLED;
        delete update[updateId];
    }

    /**
     * @dev Attempts to execute a validated risk parameter update using the RiskSteward contract
     *      Updates the `processedUpdates` mapping and emits the appropriate event based on the outcome
     * @param updateId The unique identifier of the risk parameter update
     * @param newValue The new encoded value of the parameter to be applied
     * @param updateType The type of parameter being updated (e.g., "supplyCap", "borrowCap")
     * @param market The market address (e.g., vToken) associated with the update
     */

    function _executeUpdate(
        uint256 updateId,
        bytes memory newValue,
        string memory updateType,
        address market
    ) internal {
        try
            riskParameterConfigs[updateType].riskSteward.processUpdate(
                updateId,
                newValue,
                updateType,
                market
            )
        {
            processedUpdates[updateId] = UPDATE_STATUS.PROCESSED;
            emit RiskParameterUpdateProcessed(updateId);
        } catch {
            emit RiskParameterUpdateFailed(updateId, UPDATE_STATUS.FAILED);
            processedUpdates[updateId] = UPDATE_STATUS.FAILED;
        }
    }

    /**
     * @notice Validates the status of an update silently. Will validate that the update configuration is active, is not expired and unprocessed.
     * @param updateId The ID of the update
     * @param updateType The type of update
     * @param timestamp Remote timestamp of the update
     * @return error The UPDATE_STATUS error code if the update is not valid or 0
     */
    function _validateUpdateStatus(
        uint256 updateId,
        string memory updateType,
        uint256 timestamp
    ) internal view returns (UPDATE_STATUS error) {
        if (timestamp == 0) {
            revert UpdateNotReceived(updateId);
        }

        RiskParamConfig memory config = riskParameterConfigs[updateType];
        if (!config.active) {
            return UPDATE_STATUS.CONFIG_NOT_ACTIVE;
        }

        if (timestamp + REMOTE_UPDATE_EXPIRATION_TIME < block.timestamp) {
            return UPDATE_STATUS.EXPIRED;
        }

        if (processedUpdates[updateId] == UPDATE_STATUS.PROCESSED) {
            return processedUpdates[updateId];
        }

        return UPDATE_STATUS.NONE;
    }

    /**
     * @dev Handles incoming LayerZero messages containing risk parameter update data
     *      Decodes the payload and forwards the update for processing
     * @param payload The encoded message containing update details
     */
    function _lzReceive(
        Origin calldata,
        bytes32 /*_guid*/,
        bytes calldata payload,
        address /*_executor*/,
        bytes calldata /*_extraData*/
    ) internal override {
        (
            uint256 updateId,
            bytes memory newValue,
            string memory updateType,
            address market,
            bytes memory additionalData,
            uint256 timestamp
        ) = abi.decode(payload, (uint256, bytes, string, address, bytes, uint256));

        processedUpdates[updateId] = UPDATE_STATUS.RECEIVED;
        remoteUpdateTimestamps[updateId] = block.timestamp;

        emit UpdateReceived(updateId);

        update[updateId] = RiskParameterUpdate({
            timestamp: timestamp,
            newValue: newValue,
            referenceId: "",
            previousValue: "",
            updateType: updateType,
            updateId: updateId,
            market: market,
            additionalData: additionalData
        });
    }
}

contracts/RiskSteward/RiskStewardOwner.s.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { AccessControlledV8 } from "../Governance/AccessControlledV8.sol";
import { IRiskStewardReceiver } from "../interfaces/IRiskStewardReceiver.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";

/**
 * @title RiskStewardOwner
 * @author Venus
 * @notice RiskStewardOwner contract acts as a governance and access control mechanism,
 * allowing owner to upsert signature of RiskStewardReceiver contract,
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */

contract RiskStewardOwner is AccessControlledV8 {
    /**
     *  @custom:oz-upgrades-unsafe-allow state-variable-immutable
     */
    IRiskStewardReceiver public immutable RISK_STEWARD_RECEIVER;

    /**
     * @notice Stores function signature corresponding to their 4 bytes hash value
     */
    mapping(bytes4 => string) public functionRegistry;

    /**
     * @notice Event emitted when function registry updated
     */
    event FunctionRegistryChanged(string indexed signature, bool active);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address riskStewardReceiver_) {
        ensureNonzeroAddress(riskStewardReceiver_);
        RISK_STEWARD_RECEIVER = IRiskStewardReceiver(riskStewardReceiver_);
        _disableInitializers();
    }

    /**
     * @notice Initialize the contract
     * @param accessControlManager_  Address of access control manager
     */
    function initialize(address accessControlManager_) external initializer {
        ensureNonzeroAddress(accessControlManager_);
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Invoked when called function does not exist in the contract
     * @param data_ Calldata containing the encoded function call
     * @return Result of function call
     * @custom:access Controlled by Access Control Manager
     */
    fallback(bytes calldata data_) external returns (bytes memory) {
        string memory fun = functionRegistry[msg.sig];
        require(bytes(fun).length != 0, "Function not found");
        _checkAccessAllowed(fun);
        (bool ok, bytes memory res) = address(RISK_STEWARD_RECEIVER).call(data_);
        require(ok, "call failed");
        return res;
    }

    /**
     * @notice A registry of functions that are allowed to be executed
     * @param signatures_  Function signature to be added or removed
     * @param active_ bool value, should be true to add function
     * @custom:access Only owner
     */
    function upsertSignature(string[] calldata signatures_, bool[] calldata active_) external onlyOwner {
        uint256 signatureLength = signatures_.length;
        require(signatureLength == active_.length, "Input arrays must have the same length");
        for (uint256 i; i < signatureLength; ++i) {
            bytes4 sigHash = bytes4(keccak256(bytes(signatures_[i])));
            bytes memory signature = bytes(functionRegistry[sigHash]);
            if (active_[i] && signature.length == 0) {
                functionRegistry[sigHash] = signatures_[i];
                emit FunctionRegistryChanged(signatures_[i], true);
            } else if (!active_[i] && signature.length != 0) {
                delete functionRegistry[sigHash];
                emit FunctionRegistryChanged(signatures_[i], false);
            }
        }
    }

    /**
     *  @notice Empty implementation of renounce ownership to avoid any mishappening
     */
    function renounceOwnership() public virtual override {}
}

contracts/RiskSteward/RiskStewardReceive.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { Strings } from "@openzeppelin/contracts/utils/Strings.sol";
import { IRiskSteward } from "../interfaces/IRiskSteward.sol";
import { IRiskOracle, RiskParameterUpdate } from "../interfaces/IRiskOracle.sol";
import { RiskParamConfig } from "../interfaces/IRiskStewardReceiver.sol";
import { ensureNonzeroAddress } from "@venusprotocol/solidity-utilities/contracts/validators.sol";
import { IGovernorBravoDelegate, GovernorBravoDelegateStorageV2 } from "../Governance/IGovernorBravoV8.sol";
import { IOmnichainProposalSender } from "../Cross-chain/interfaces/IOmnichainProposalSender.sol";
import { RiskStewardReceiverBase } from "./RiskStewardReceiverBase.sol";
import { OApp, MessagingFee, Origin } from "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";
/**
 * @title RiskStewardReceiver
 * @author Venus
 * @notice Contract that can read updates from the Chaos Labs Risk Oracle, validate them, and push them to the correct RiskSteward.
 * @custom:security-contact https://github.com/VenusProtocol/governance-contracts#discussion
 */
contract RiskStewardReceiver is OApp, RiskStewardReceiverBase {
    enum UPDATE_STATUS {
        NONE,
        PROCESSED,
        SEND_TO_DESTINATION_CHAIN,
        CONFIG_NOT_ACTIVE,
        EXPIRED,
        FAILED,
        PROPOSED,
        INVALID_DESTINATION_CHAIN
    }

    struct ProposalActions {
        address[] targets;
        uint256[] values;
        string[] signatures;
        bytes[] datas;
    }

    struct ProposalParams {
        uint32 destChainId;
        address target;
        uint256 value;
        string signature;
        bytes data;
    }
    struct RemoteProposalParams {
        uint32 destChainId;
        uint256 proposalId;
        address target;
        uint256 value;
        string signature;
        bytes data;
    }

    struct RemoteProposal {
        uint32 destChainId;
        uint256 proposalId;
        address[] targets;
        uint256[] values;
        string[] signatures;
        bytes[] datas;
    }

    bytes32 private constant INDEX_CACHE_SLOT = keccak256(abi.encode("remote-index-cache"));

    bytes32 private constant COUNT_CACHE_SLOT = keccak256(abi.encode("remote-count-cache"));

    /**
     * @notice Source chain id
     */
    uint32 public immutable LAYER_ZERO_CHAIN_ID;

    /**
     * @notice Whitelisted oracle address to receive updates from
     */
    IRiskOracle public immutable RISK_ORACLE;

    /**
     * @notice Address of the GovernorBravo used to propose VIPs
     */
    IGovernorBravoDelegate public immutable GOVERNANCE_BRAVO;

    /**
     * @notice Address of the OmnichainProposalSender used to propose VIPs
     */
    IOmnichainProposalSender public immutable OMNICHAIN_PROPOSAL_SENDER;

    /**
     * @notice Mapping from LayerZero V2 chain ID to V1 chain ID
     */
    mapping(uint32 => uint16) public lzV2ToV1ChainId;

    /**
     * @notice Mapping of processed updates. Used to prevent re-execution
     */
    mapping(uint256 updateId => UPDATE_STATUS) public processedUpdates;

    /**
     * @notice Mapping of supported risk configurations and their validation parameters
     */
    mapping(uint32 destChainId => address) public remoteRiskStewardReceiver;

    /// @notice Emitted when a V2 → V1 chain ID mapping is set or deleted
    event ChainIdMappingUpdated(uint32 indexed v2ChainId, uint16 v1ChainId);

    /**
     * @notice Event emitted when an update is send through LZ on dest chain with update id and LZ send receipt
     */
    event RiskParameterUpdateSend(uint32 destChainId, uint256 indexed updateId);

    /**
     * @notice Event emitted when an update is proposed with proposal id and update id
     */
    event RiskParameterUpdateProposed(uint256 indexed updateId);

    /**
     * @notice Emit when sets the remote receiver for a destination chain
     */
    event RemoteRiskStewardReceiverUpdated(
        uint32 indexed destChainId,
        address previousRemoteReceiver,
        address newRemoteReceiver
    );

    /**
     * @notice Emitted when applying an update fails to validate or execute
     */
    event RiskParameterUpdateFailed(uint256 indexed updateId, UPDATE_STATUS indexed error);

    /**
     *  @notice Emitted when processing a remote risk parameter update fails via LayerZero
     */
    event RemoteRiskParameterUpdateFailed(
        uint32 destChainId,
        bytes payload,
        bytes _options,
        MessagingFee fee,
        address sender,
        bytes reason
    );

    constructor(
        address riskOracle_,
        uint32 layerZeroChainId_,
        address endpoint_,
        address owner_,
        address governorBravo_,
        address omnichainProposalSender_
    ) OApp(endpoint_, owner_) {
        ensureNonzeroAddress(riskOracle_);
        RISK_ORACLE = IRiskOracle(riskOracle_);
        LAYER_ZERO_CHAIN_ID = layerZeroChainId_;
        GOVERNANCE_BRAVO = IGovernorBravoDelegate(governorBravo_);
        OMNICHAIN_PROPOSAL_SENDER = IOmnichainProposalSender(omnichainProposalSender_);
    }

    /**
     * @notice Sets the remote receiver for a destination chain
     * @param destChainId The destination chain ID
     * @param remoteReceiver The address of the remote receiver
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits RemoteRiskStewardReceiverUpdated with the destination chain ID and the remote receiver
     * @custom:error Throws ZeroAddressNotAllowed if the remote receiver address is zero
     */
    function setRemoteRiskStewardReceiver(uint32 destChainId, address remoteReceiver) external onlyOwner {
        ensureNonzeroAddress(remoteReceiver);
        emit RemoteRiskStewardReceiverUpdated(destChainId, remoteRiskStewardReceiver[destChainId], remoteReceiver);
        remoteRiskStewardReceiver[destChainId] = remoteReceiver;
    }

    /**
     * @notice Deletes the remote receiver for a destination chain
     * @param destChainId The destination chain ID
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits RemoteRiskStewardReceiverUpdated with the destination chain ID and the remote receiver
     * @custom:error Throws ZeroAddressNotAllowed if the remote receiver address is zero
     */
    function deleteRemoteRiskStewardReceiver(uint32 destChainId) external onlyOwner {
        ensureNonzeroAddress(remoteRiskStewardReceiver[destChainId]);

        emit RemoteRiskStewardReceiverUpdated(destChainId, remoteRiskStewardReceiver[destChainId], address(0));
        remoteRiskStewardReceiver[destChainId] = address(0);
    }

    /**
     * @notice Sets or deletes multiple V2 → V1 chain ID mappings in a single transaction.
     * @dev If an element of `v1ChainIds` is 0, the corresponding mapping is deleted.
     * @param v2ChainIds Array of LayerZero V2 chain IDs to set.
     * @param v1ChainIds Array of LayerZero V1 chain IDs (or 0 to delete).
     */
    function setDestChainIdMappings(uint32[] calldata v2ChainIds, uint16[] calldata v1ChainIds) external onlyOwner {
        uint256 len = v2ChainIds.length;
        require(len == v1ChainIds.length, "Array length mismatch");

        for (uint256 i; i < len; ++i) {
            uint32 v2 = v2ChainIds[i];
            uint16 v1 = v1ChainIds[i];

            uint16 v1ChainId = lzV2ToV1ChainId[v2];
            if (v1 == 0) {
                // Delete mapping if V1 is 0
                if (v1ChainId != 0) {
                    delete lzV2ToV1ChainId[v2];
                    emit ChainIdMappingUpdated(v2, 0);
                }
            } else {
                if (v1ChainId != v1) {
                    lzV2ToV1ChainId[v2] = v1;
                    emit ChainIdMappingUpdated(v2, v1);
                }
            }
        }
    }

    /**
     * @notice Processes an update by its ID. Validates that the update configuration is active, not expired, and unprocessed.
     * @dev Handles updates based on their type and destination chain:
     * - For MarketCap updates on the BNB chain, directly invokes the associated RiskSteward contract.
     * - For MarketCap updates on remote chains, constructs and sends a payload to the destination chain’s RiskStewardReceiver via the LayerZero bridge.
     * - For critical updates (e.g., reserve factor), creates a governance proposal on the Governor Bravo contract for execution.
     * @param updateId The ID of the update to process
     * @param options LayerZero call options
     * @param ZROTokens Amount of ZRO tokens approved for fee payment (used in LayerZero).
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     * @custom:event Emits RiskParameterUpdateFailed if the update is invalid.
     */
    function processUpdateById(
        uint256 updateId,
        bytes calldata options,
        uint256 ZROTokens,
        bytes calldata adapterParams
    ) external payable whenNotPaused {
        RiskParameterUpdate memory update = RISK_ORACLE.getUpdateById(updateId);
        (UPDATE_STATUS error, uint32 destChainId) = _validateUpdateStatus(update);

        if (error == UPDATE_STATUS.NONE) {
            _executeUpdateByType(update, destChainId, options, ZROTokens, adapterParams);
        } else {
            processedUpdates[update.updateId] = error;
            emit RiskParameterUpdateFailed(update.updateId, error);
        }
    }

    /**
     * @notice Processes the latest update for a given parameter and market. Validates that the update configuration is active, not expired, and unprocessed.
     * @dev Handles updates based on their type and destination chain:
     * - For MarketCap updates on the BNB chain, directly invokes the associated RiskSteward contract.
     * - For MarketCap updates on remote chains, constructs and sends a payload to the destination chain’s RiskStewardReceiver via the LayerZero bridge.
     * - For critical updates (e.g., reserve factor), creates a governance proposal on the Governor Bravo contract for execution.
     * @param updateType The type of update to process
     * @param market The market to process the update for
     * @param options LayerZero message options
     * @param ZROTokens Amount of ZRO tokens used for the message fee
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     * @custom:event Emits RiskParameterUpdateFailed if the update is invalid.
     */
    function processUpdateByParameterAndMarket(
        string memory updateType,
        address market,
        bytes calldata options,
        uint256 ZROTokens,
        bytes calldata adapterParams
    ) external payable whenNotPaused {
        RiskParameterUpdate memory update = RISK_ORACLE.getLatestUpdateByParameterAndMarket(updateType, market);
        (UPDATE_STATUS error, uint32 destChainId) = _validateUpdateStatus(update);
        if (error == UPDATE_STATUS.NONE) {
            _executeUpdateByType(update, destChainId, options, ZROTokens, adapterParams);
        } else {
            processedUpdates[update.updateId] = error;
            emit RiskParameterUpdateFailed(update.updateId, error);
        }
    }

    /**
     * @notice Proposes a list of updates by their IDs. Supports all types of updates including market cap and critical parameters.
     * @dev Each update is validated to ensure it is active, not expired, and unprocessed.
     * - All updates on remote chains are grouped and reduced into a single remote proposal for efficiency.
     * - all updateTypes including MarketCap updates are proposed to governance via a fast track proposal.
     * @param updateIds The IDs of the updates to process
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     * @custom:event Emits RiskParameterUpdated with the update ID
     * @custom:event Emits RiskParameterUpdateProposed with the update IDs
     * @custom:event Emits UpdateFailed with the update ID and the error if validation fails for an update
     * @custom:error Throws UpdateIsExpired if the update is expired
     */
    function proposeUpdatesByIds(uint256[] memory updateIds, bytes calldata adapterParams) external {
        (
            uint32 destinationChainCount,
            uint256 validProposalCount,
            RiskParameterUpdate[] memory updates
        ) = _validateProposeUpdateAndDestChainIds(updateIds);
        _sendProposals(destinationChainCount, validProposalCount, updates, adapterParams);
    }

    /**
     * @notice Sends a message via LayerZero.
     * @param destChainId Destination chain ID.
     * @param payload Encoded message payload.
     * @param options LayerZero message options.
     * @param fee Messaging fee structure.
     */

    function lzSend(
        uint32 destChainId,
        bytes calldata payload,
        bytes calldata options,
        MessagingFee calldata fee,
        address refundAddress
    ) external payable {
        require(msg.sender == address(this), "Invalid caller");
        _lzSend(destChainId, payload, options, fee, refundAddress);
    }

    /**
     * @notice Quotes the gas needed to pay for the full omnichain transaction in native gas or ZRO token.
     * @param dstEid Destination chain's endpoint ID.
     * @param message The message.
     * @param options Message execution options (e.g., for sending gas to destination).
     * @param payInLzToken Whether to return fee in ZRO token.
     * @return fee A `MessagingFee` struct containing the calculated gas fee in either the native token or ZRO token.
     */
    function quote(
        uint32 dstEid,
        string memory message,
        bytes memory options,
        bool payInLzToken
    ) public view returns (MessagingFee memory fee) {
        bytes memory payload = abi.encode(message);
        fee = _quote(dstEid, payload, options, payInLzToken);
    }

    /**
     *  @notice Empty implementation of renounce ownership to avoid any mishappening
     */
    function renounceOwnership() public override {}
    /**
     * @notice Executes the update based on its updateType.
     * @param update The risk parameter update to process
     * @param destChainId The LayerZero destination chain ID for the proposal
     * @param options Additional options for LayerZero messaging
     * @param ZROTokens The amount of ZRO tokens to be used for message fees
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     */
    function _executeUpdateByType(
        RiskParameterUpdate memory update,
        uint32 destChainId,
        bytes calldata options,
        uint256 ZROTokens,
        bytes calldata adapterParams
    ) internal {
        if (isSupplyOrBorrowCapUpdate(update.updateType)) {
            _executeOrSendUpdatePayload(update, options, ZROTokens);
        } else {
            _sendProposal(update, destChainId, adapterParams);
        }
    }

    /**
     * @dev Executes a single update locally or forwards it to the remote chain
     * @param update The RiskParameterUpdate to execute if on BNB chain or prepare parameters for if on a remote chain
     * @param options LayerZero options for the message
     * @param ZROTokens Amount of ZRO tokens used for the message fee
     */
    function _executeOrSendUpdatePayload(
        RiskParameterUpdate memory update,
        bytes calldata options,
        uint256 ZROTokens
    ) internal {
        IRiskSteward riskSteward = riskParameterConfigs[update.updateType].riskSteward;
        (, uint32 destChainId) = riskSteward.decodeAdditionalData(update.additionalData);

        if (LAYER_ZERO_CHAIN_ID == destChainId) {
            try riskSteward.processUpdate(update.updateId, update.newValue, update.updateType, update.market) {
                processedUpdates[update.updateId] = UPDATE_STATUS.PROCESSED;
                emit RiskParameterUpdateProcessed(update.updateId);
            } catch {
                emit RiskParameterUpdateFailed(update.updateId, UPDATE_STATUS.FAILED);
                processedUpdates[update.updateId] = UPDATE_STATUS.FAILED;
            }
        } else {
            bytes memory payload = _createRemotePayload(update);
            // Send layer zero message directly
            try
                this.lzSend{ value: msg.value }(
                    destChainId,
                    payload,
                    options,
                    MessagingFee(msg.value, ZROTokens),
                    msg.sender
                )
            {
                emit RiskParameterUpdateSend(destChainId, update.updateId);
                processedUpdates[update.updateId] = UPDATE_STATUS.SEND_TO_DESTINATION_CHAIN;
            } catch (bytes memory reason) {
                emit RemoteRiskParameterUpdateFailed(
                    destChainId,
                    payload,
                    options,
                    MessagingFee(msg.value, ZROTokens),
                    msg.sender,
                    reason
                );
                processedUpdates[update.updateId] = UPDATE_STATUS.FAILED;
            }
        }
    }

    /**
     * @notice Proposes a risk parameter update by routing it to the appropriate destination.
     * @param update The risk parameter update to be proposed.
     * @param destChainId The LayerZero chain ID of the destination chain for the proposal.
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     */
    function _sendProposal(
        RiskParameterUpdate memory update,
        uint32 destChainId,
        bytes calldata adapterParams
    ) internal {
        if (LAYER_ZERO_CHAIN_ID == destChainId) {
            _sendBscProposal(update);
        } else {
            _sendRemoteProposal(update, destChainId, adapterParams);
        }
        processedUpdates[update.updateId] = UPDATE_STATUS.PROPOSED;
        emit RiskParameterUpdateProposed(update.updateId);
    }

    /**
     * @notice Creates and submits a governance proposal specifically for the BNB Chain (BSC)
     * @dev Wraps the given update into a standard proposal format.
     * It constructs the call data and delegates the proposal creation to `_proposeUpdate`.
     * @param update The risk parameter update to propose as a BSC-specific governance proposal
     * @return proposalId The ID of the proposal created through the governance contract
     */
    function _sendBscProposal(RiskParameterUpdate memory update) internal returns (uint256 proposalId) {
        (address target, uint256 value, string memory signature, bytes memory data) = _createBscProposal(update);
        address[] memory remoteProposalTargets = new address[](1);
        remoteProposalTargets[0] = target;
        uint256[] memory remoteProposalValues = new uint256[](1);
        remoteProposalValues[0] = value;
        string[] memory remoteProposalSignatures = new string[](1);
        remoteProposalSignatures[0] = signature;
        bytes[] memory remoteProposalDatas = new bytes[](1);
        remoteProposalDatas[0] = data;
        proposalId = _proposeUpdate(
            remoteProposalTargets,
            remoteProposalValues,
            remoteProposalSignatures,
            remoteProposalDatas
        );
    }

    /**
     * @notice Prepares and sends a remote proposal to a remote destination chain.
     * Constructs the proposal payload, wraps it with remote execution parameters, and submits it.
     * @param update The risk parameter update to propose on a remote chain
     * @param destChainId The LayerZero chain ID of the target remote chain
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     * @return proposalId The ID of the newly submitted proposal
     */
    function _sendRemoteProposal(
        RiskParameterUpdate memory update,
        uint32 destChainId,
        bytes calldata adapterParams
    ) internal returns (uint256 proposalId) {
        proposalId = OMNICHAIN_PROPOSAL_SENDER.proposalCount();
        (address target, uint256 value, string memory signature, bytes memory data) = _generateRemotePayload(
            update,
            destChainId
        );
        ProposalActions memory proposal;
        proposal.targets = new address[](1);
        proposal.values = new uint256[](1);
        proposal.signatures = new string[](1);
        proposal.datas = new bytes[](1);
        proposal.targets[0] = target;
        proposal.values[0] = value;
        proposal.signatures[0] = signature;
        proposal.datas[0] = data;
        RemoteProposalParams memory remoteProposalParams = _createRemoteProposal(
            destChainId,
            proposalId,
            proposal.targets,
            proposal.values,
            proposal.signatures,
            proposal.datas,
            adapterParams
        );
        address[] memory remoteProposalTargets = new address[](1);
        remoteProposalTargets[0] = remoteProposalParams.target;
        uint256[] memory remoteProposalValues = new uint256[](1);
        remoteProposalValues[0] = remoteProposalParams.value;
        string[] memory remoteProposalSignatures = new string[](1);
        remoteProposalSignatures[0] = remoteProposalParams.signature;
        bytes[] memory remoteProposalDatas = new bytes[](1);
        remoteProposalDatas[0] = remoteProposalParams.data;

        proposalId = _proposeUpdate(
            remoteProposalTargets,
            remoteProposalValues,
            remoteProposalSignatures,
            remoteProposalDatas
        );
    }

    /**
     * @notice Batches remote and bnb updates into a single proposal.
     * @dev This function handles all valid updates. Updates targeting the BNB chain are added directly.
     * Remote updates are grouped by destination chain and batched into single actions per chain.
     * All updates—both BNB and remote—are proposed together in one fast-track governance proposal.
     * @param destinationChainCount Number of unique destination chains involved in the updates
     * @param validProposalCount Number of valid (non-expired, unprocessed) updates to be included
     * @param updates Array of `RiskParameterUpdate` structs representing each proposed parameter change
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     * @custom:event Emits `RiskParameterUpdateProposed` for every successfully processed update
     */
    function _sendProposals(
        uint32 destinationChainCount,
        uint256 validProposalCount,
        RiskParameterUpdate[] memory updates,
        bytes calldata adapterParams
    ) internal {
        uint32[] memory destChainIds = new uint32[](destinationChainCount);
        address[][] memory remoteTargets = new address[][](destChainIds.length);
        uint256[][] memory remoteValues = new uint256[][](destChainIds.length);
        string[][] memory remoteSignatures = new string[][](destChainIds.length);
        bytes[][] memory remoteDatas = new bytes[][](destChainIds.length);
        ProposalActions memory allProposals;
        allProposals.targets = new address[](validProposalCount);
        allProposals.values = new uint256[](validProposalCount);
        allProposals.signatures = new string[](validProposalCount);
        allProposals.datas = new bytes[](validProposalCount);
        uint256 ind = 0;

        for (uint256 i; i < updates.length; ++i) {
            RiskParameterUpdate memory update = updates[i];
            if (Strings.equal(update.updateType, "")) {
                // Skip indexes of invalid updates
                continue;
            }
            ProposalParams memory p = _prepareProposalParams(update);

            if (processedUpdates[update.updateId] == UPDATE_STATUS.NONE) {
                if (LAYER_ZERO_CHAIN_ID == p.destChainId) {
                    allProposals.targets[ind] = p.target;
                    allProposals.values[ind] = p.value;
                    allProposals.signatures[ind] = p.signature;
                    allProposals.datas[ind] = p.data;
                    ind++;
                    processedUpdates[update.updateId] = UPDATE_STATUS.PROPOSED;
                    emit RiskParameterUpdateProposed(update.updateId);
                    continue;
                }
                uint256 index = readUint256Cache(INDEX_CACHE_SLOT, p.destChainId) - 1;
                uint256 actionCount = getAndUpdateActionIndex(p.destChainId);
                if (remoteTargets[index].length == 0) {
                    destChainIds[index] = p.destChainId;
                    remoteTargets[index] = new address[](actionCount + 1);
                    remoteValues[index] = new uint256[](actionCount + 1);
                    remoteSignatures[index] = new string[](actionCount + 1);
                    remoteDatas[index] = new bytes[](actionCount + 1);
                }

                remoteTargets[index][actionCount] = p.target;
                remoteValues[index][actionCount] = p.value;
                remoteSignatures[index][actionCount] = p.signature;
                remoteDatas[index][actionCount] = p.data;
                processedUpdates[update.updateId] = UPDATE_STATUS.PROPOSED;
                emit RiskParameterUpdateProposed(update.updateId);
            }
        }

        ProposalActions memory remoteProposal = _createRemoteProposals(
            destChainIds,
            remoteTargets,
            remoteValues,
            remoteSignatures,
            remoteDatas,
            adapterParams
        );

        for (uint256 i; i < destChainIds.length; ++i) {
            allProposals.targets[ind] = remoteProposal.targets[i];
            allProposals.values[ind] = remoteProposal.values[i];
            allProposals.signatures[ind] = remoteProposal.signatures[i];
            allProposals.datas[ind] = remoteProposal.datas[i];
            ind++;
        }
        _proposeUpdate(allProposals.targets, allProposals.values, allProposals.signatures, allProposals.datas);
    }

    /**
     * @notice prepares parameters for a remote proposal or a BSC proposal.
     * @param update The RiskParameterUpdate to execute on any chain
     * @custom:event Emits BatchedUpdateFailed with the update ID if the update fails to execute
     * @return ProposalParams proposal parameters
     */
    function _prepareProposalParams(RiskParameterUpdate memory update) internal view returns (ProposalParams memory) {
        IRiskSteward riskSteward = riskParameterConfigs[update.updateType].riskSteward;
        (, uint32 destChainId_) = riskSteward.decodeAdditionalData(update.additionalData);
        if (LAYER_ZERO_CHAIN_ID == destChainId_) {
            (address target_, uint256 value_, string memory signature_, bytes memory payload) = _createBscProposal(
                update
            );
            return (ProposalParams(destChainId_, target_, value_, signature_, payload));
        } else {
            (address target_, uint256 value_, string memory signature_, bytes memory payload) = _generateRemotePayload(
                update,
                destChainId_
            );
            return (ProposalParams(destChainId_, target_, value_, signature_, payload));
        }
    }

    /**
     * @notice Reduces a collection or remote proposal parameters into a single command for execution on the remote chain
     * @param destChainIds The destination chain IDs of the updates
     * @param targets The targets of the updates
     * @param values The values of the updates
     * @param signatures The signatures of the updates
     * @param datas The data of the updates
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     */
    function _createRemoteProposals(
        uint32[] memory destChainIds,
        address[][] memory targets,
        uint256[][] memory values,
        string[][] memory signatures,
        bytes[][] memory datas,
        bytes calldata adapterParams
    ) internal returns (ProposalActions memory remoteProposalActions) {
        RemoteProposal memory remoteProposal = RemoteProposal({
            destChainId: 0,
            proposalId: 0,
            targets: new address[](destChainIds.length),
            values: new uint256[](destChainIds.length),
            signatures: new string[](destChainIds.length),
            datas: new bytes[](destChainIds.length)
        });

        uint256 proposalId = OMNICHAIN_PROPOSAL_SENDER.proposalCount();
        for (uint256 i; i < destChainIds.length; ++i) {
            RemoteProposalParams memory remoteProposalParams = _createRemoteProposal(
                destChainIds[i],
                proposalId,
                targets[i],
                values[i],
                signatures[i],
                datas[i],
                adapterParams
            );

            remoteProposal.destChainId = remoteProposalParams.destChainId;
            remoteProposal.proposalId = remoteProposalParams.proposalId;
            remoteProposal.targets[i] = remoteProposalParams.target;
            remoteProposal.values[i] = remoteProposalParams.value;
            remoteProposal.signatures[i] = remoteProposalParams.signature;
            remoteProposal.datas[i] = remoteProposalParams.data;
        }
        return
            ProposalActions(
                remoteProposal.targets,
                remoteProposal.values,
                remoteProposal.signatures,
                remoteProposal.datas
            );
    }

    /**
     * @notice Creates a fast-track governance proposal using the provided call data.
     * @dev This function wraps multiple on-chain or cross-chain actions into a single fast-track proposal
     * submitted to the Governor Bravo contract.
     * @param targets Array of target contract addresses for each call
     * @param values Array of ETH values (in wei) to send with each call
     * @param signatures Array of function signatures for each call
     * @param datas Array of encoded call data corresponding to each function
     * @return proposalId The ID of the newly created proposal
     */
    function _proposeUpdate(
        address[] memory targets,
        uint256[] memory values,
        string[] memory signatures,
        bytes[] memory datas
    ) internal returns (uint256 proposalId) {
        proposalId = GOVERNANCE_BRAVO.propose(
            targets,
            values,
            signatures,
            datas,
            "",
            GovernorBravoDelegateStorageV2.ProposalType.FASTTRACK
        );
        return proposalId;
    }

    /**
     * @notice Fetches updates and indexes them by their destination chain ID
     * @dev For each valid and unprocessed update:
     * - If it's destined for a remote chain, assigns it an index and counts actions for batching.
     * - If it's for the local chain, it will be processed directly.
     * Updates that are invalid (expired, already processed, etc.) will be skipped and emitted as failed.
     * @param updateIds The IDs of the updates to organize
     * @return destinationChainCount number of dstination chian on which proposal needs to be submited
     * @return validProposalCount number of total valid proposals which will be created
     * @return updates The RiskParameterUpdate array of updates in order of the updateIds array argument
     */
    function _validateProposeUpdateAndDestChainIds(
        uint256[] memory updateIds
    )
        internal
        returns (uint32 destinationChainCount, uint256 validProposalCount, RiskParameterUpdate[] memory updates)
    {
        updates = new RiskParameterUpdate[](updateIds.length);
        uint32 baseOneIndex = 1;
        validProposalCount = 0;

        for (uint256 i; i < updateIds.length; ++i) {
            RiskParameterUpdate memory update = RISK_ORACLE.getUpdateById(updateIds[i]);
            (UPDATE_STATUS error, uint32 destChainId) = _validateUpdateStatus(update);

            if (error == UPDATE_STATUS.NONE) {
                if (destChainId != LAYER_ZERO_CHAIN_ID) {
                    uint256 index = readUint256Cache(INDEX_CACHE_SLOT, destChainId);
                    uint256 actionCount = readUint256Cache(COUNT_CACHE_SLOT, destChainId);
                    if (index == 0) {
                        writeUint256Cache(INDEX_CACHE_SLOT, destChainId, baseOneIndex);
                        baseOneIndex++;
                        validProposalCount++;
                    }
                    writeUint256Cache(COUNT_CACHE_SLOT, destChainId, actionCount + 1);
                } else {
                    validProposalCount++;
                }
                updates[i] = update;
            } else {
                emit RiskParameterUpdateFailed(update.updateId, error);
            }
        }
        return (baseOneIndex - 1, validProposalCount, updates);
    }

    /**
     * @notice Creates a governance proposal payload for a market cap update on the BNB chain.
     * @dev Constructs the call data for invoking `processUpdate` on the associated RiskSteward contract.
     * The proposal is formed with the target RiskSteward, zero ETH value, the function signature, and encoded arguments.
     * @param update The RiskParameterUpdate object containing update details such as ID, value, type, and market
     * @return target The address of the RiskSteward contract that will execute the update
     * @return value The amount of ETH to send
     * @return signature The function signature to be called in the proposal ("processUpdate(uint256,bytes,string,address)")
     * @return data The ABI-encoded payload containing updateId, packed new value, update type, and market address
     */
    function _createBscProposal(
        RiskParameterUpdate memory update
    ) internal view returns (address target, uint256 value, string memory signature, bytes memory data) {
        IRiskSteward riskSteward = riskParameterConfigs[update.updateType].riskSteward;

        bytes memory payload = abi.encode(
            update.updateId,
            riskSteward.packNewValue(update.newValue),
            update.updateType,
            update.market
        );
        return (address(riskSteward), 0, "processUpdate(uint256,bytes,string,address)", payload);
    }

    /**
     * @notice Creates a proposal payload to be sent to the remote RiskStewardReceiver for a given update.
     * @param update The update to create a remote proposal for
     * @return target The target of the update
     * @return value Hardcoded as zero since no value is required to process an update
     * @return signature Hardcoded as "processUpdate(bytes,bytes,string,address,bytes)" since this is the signature for the processUpdate function
     * @return data The data in bytes of the update
     */
    function _generateRemotePayload(
        RiskParameterUpdate memory update,
        uint32 destChainId
    ) internal view returns (address target, uint256 value, string memory signature, bytes memory data) {
        IRiskSteward riskSteward = riskParameterConfigs[update.updateType].riskSteward;
        address remoteReceiver = remoteRiskStewardReceiver[destChainId];

        bytes memory payload = abi.encode(
            update.updateId,
            riskSteward.packNewValue(update.newValue),
            update.updateType,
            update.market,
            update.timestamp
        );
        return (remoteReceiver, 0, "processUpdate(uint256,bytes,string,address,uint256)", payload);
    }

    /**
     * @notice Creates a remote proposal params for updates to be executed on a remote chain.
     * @param destChainId The destination chain ID of the update
     * @param proposalId The proposal ID of the update
     * @param targets The targets of the update
     * @param values The values of the update
     * @param signatures The signatures of the update
     * @param datas The data of the update
     * @param adapterParams Optional adapter parameters for custom gas limits or message execution behavior.
     * @return remoteProposalParams The remote proposal params
     */
    function _createRemoteProposal(
        uint32 destChainId,
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        string[] memory signatures,
        bytes[] memory datas,
        bytes calldata adapterParams
    ) internal view returns (RemoteProposalParams memory remoteProposalParams) {
        uint16 lzV1DestChainId = lzV2ToV1ChainId[destChainId];
        require(lzV1DestChainId != 0, "invalid lzV1DestChainId");

        bytes memory payload = abi.encode(
            targets,
            values,
            signatures,
            datas,
            GovernorBravoDelegateStorageV2.ProposalType.FASTTRACK
        );

        bytes memory payloadWithId = abi.encode(payload, proposalId);
        bytes memory adapterParams_ = adapterParams.length == 0
            ? abi.encodePacked(uint16(1), uint256(800000))
            : adapterParams;

        uint256 fee = _getRemoteProposalFee(lzV1DestChainId, payloadWithId, adapterParams_);
        return
            RemoteProposalParams({
                destChainId: lzV1DestChainId,
                proposalId: proposalId,
                target: address(OMNICHAIN_PROPOSAL_SENDER),
                value: fee,
                signature: "execute(uint16,bytes,bytes,address)",
                data: abi.encode(lzV1DestChainId, payload, adapterParams_, address(0))
            });
    }

    /**
     * @notice Estimates the fee needed to receive and execute a proposal on a remote chain
     * @param destChainId The destination chain ID of the update
     * @param payloadWithId The payload with the proposal ID
     * @param adapterParams adapter parameters for custom gas limits or message execution behavior.
     * @return estimatedFee The estimated fee
     */
    function _getRemoteProposalFee(
        uint32 destChainId,
        bytes memory payloadWithId,
        bytes memory adapterParams
    ) internal view returns (uint256) {
        (uint256 fee, ) = OMNICHAIN_PROPOSAL_SENDER.estimateFees(
            uint16(destChainId),
            payloadWithId,
            false,
            adapterParams
        );
        return fee;
    }

    /**
     * @dev Creates a remote proposal params for a given update.
     * @param update The update to create a remote proposal for
     * @return data The data in bytes of the update
     */
    function _createRemotePayload(RiskParameterUpdate memory update) internal view returns (bytes memory data) {
        IRiskSteward riskSteward = riskParameterConfigs[update.updateType].riskSteward;

        bytes memory payload = abi.encode(
            update.updateId,
            riskSteward.packNewValue(update.newValue),
            update.updateType,
            update.market,
            update.additionalData,
            update.timestamp
        );

        return payload;
    }

    /**
     * @dev Validates the status of an update silently. Will validate that the update configuration is active, is not expired, and unprocessed
     * @return error The UPDATE_STATUS error code if the update is not valid or 0 and destination chain id
     */
    function _validateUpdateStatus(
        RiskParameterUpdate memory update
    ) internal view returns (UPDATE_STATUS error, uint32) {
        require(update.updateId != 0, "No update found");

        RiskParamConfig memory config = riskParameterConfigs[update.updateType];

        RiskParameterUpdate memory latestForMarketAndType = RISK_ORACLE.getLatestUpdateByParameterAndMarket(
            update.updateType,
            update.market
        );

        (, uint32 destChainId) = config.riskSteward.decodeAdditionalData(update.additionalData);

        if (latestForMarketAndType.updateId != update.updateId) {
            return (UPDATE_STATUS.EXPIRED, destChainId);
        }

        if (!config.active) {
            return (UPDATE_STATUS.CONFIG_NOT_ACTIVE, destChainId);
        }

        if (update.timestamp + UPDATE_EXPIRATION_TIME < block.timestamp) {
            return (UPDATE_STATUS.EXPIRED, destChainId);
        }

        if (
            processedUpdates[update.updateId] == UPDATE_STATUS.PROCESSED ||
            processedUpdates[update.updateId] == UPDATE_STATUS.SEND_TO_DESTINATION_CHAIN ||
            processedUpdates[update.updateId] == UPDATE_STATUS.PROPOSED
        ) {
            return (processedUpdates[update.updateId], destChainId);
        }

        address remoteReceiver = remoteRiskStewardReceiver[destChainId];
        if (
            !isSupplyOrBorrowCapUpdate(update.updateType) &&
            remoteReceiver == address(0) &&
            destChainId != LAYER_ZERO_CHAIN_ID
        ) {
            return (UPDATE_STATUS.INVALID_DESTINATION_CHAIN, destChainId);
        }

        return (UPDATE_STATUS.NONE, destChainId);
    }

    /**
     * @dev LayerZero message receive hook
     */
    function _lzReceive(
        Origin calldata origin,
        bytes32 guid,
        bytes calldata message,
        address executor,
        bytes calldata extraData
    ) internal virtual override {}

    /**
     * @dev Checks if the update type is a supplyCap or borrowCap update
     * @param updateType The string name of the update type
     * @return Whether the update type is supported
     */
    function isSupplyOrBorrowCapUpdate(string memory updateType) internal pure returns (bool) {
        if (Strings.equal(updateType, "supplyCap") || Strings.equal(updateType, "borrowCap")) {
            return true;
        }
        return false;
    }

    /**
     * @notice Fetches and decrements the cached action count for a given destination chain ID.
     * @param destChainId The destination chain ID whose action index is being updated
     * @return actionIndex The updated (decremented) action index
     */
    function getAndUpdateActionIndex(uint32 destChainId) internal returns (uint256) {
        uint256 actionIndex = readUint256Cache(COUNT_CACHE_SLOT, destChainId);
        if (actionIndex != 0) {
            actionIndex = actionIndex - 1;
        }
        writeUint256Cache(COUNT_CACHE_SLOT, destChainId, actionIndex);
        return actionIndex;
    }

    /**
     * @notice Writes a uint256 value to transient storage under a computed slot key.
     * @param slot The base slot identifier (e.g., COUNT_CACHE_SLOT or INDEX_CACHE_SLOT)
     * @param key The secondary key
     * @param value The uint256 value to be stored in the transient storage
     */
    function writeUint256Cache(bytes32 slot, uint32 key, uint256 value) internal {
        bytes32 slotKey = keccak256(abi.encode(slot, key));
        assembly ("memory-safe") {
            tstore(slotKey, value)
        }
    }

    /**
     * @notice Reads a cached uint256 value from transient storage using a computed slot key.
     * @param slot The base slot identifier used for organizing different cached data types
     * @param key A secondary identifier
     * @return value The uint256 value stored under the derived transient slot
     */
    function readUint256Cache(bytes32 slot, uint32 key) internal view returns (uint256 value) {
        bytes32 slotKey = keccak256(abi.encode(slot, key));
        assembly ("memory-safe") {
            value := tload(slotKey)
        }
    }
}

